BEGIN IMMEDIATE;

-- v0.33 adds story series: multi-part readings of one long work, each part a
-- complete long story (12-18 sections) that follows a located public witness
-- in order. Journey to the West gains five parts after ch. 1-7, the Rāmāyaṇa
-- is retold book by book (Books I-VI), and the Odyssey in two parts covering
-- all twenty-four books. Every section keeps its own anchor claim with
-- evidence at the same locator. A series records the source span of each
-- part and names the chapters it skips; it never fills them in. Reading
-- routes keep their own CHECK list, so series get their own tables.

CREATE TABLE IF NOT EXISTS story_series (
    id TEXT PRIMARY KEY,
    title_zh TEXT NOT NULL,
    title_en TEXT NOT NULL,
    work_entity_id TEXT REFERENCES entities(id),
    primary_source_id TEXT NOT NULL REFERENCES sources(id),
    primary_civilization_id TEXT REFERENCES civilizations(id),
    description_zh TEXT NOT NULL,
    description_en TEXT NOT NULL,
    selection_note TEXT NOT NULL,
    featured_order INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS story_series_parts (
    series_id TEXT NOT NULL REFERENCES story_series(id) ON DELETE CASCADE,
    part_order INTEGER NOT NULL CHECK(part_order >= 1),
    story_id TEXT NOT NULL REFERENCES stories(id) ON DELETE CASCADE,
    part_label_zh TEXT NOT NULL,
    part_label_en TEXT NOT NULL,
    source_span TEXT NOT NULL,
    gap_note TEXT,
    PRIMARY KEY(series_id, part_order),
    UNIQUE(series_id, story_id),
    UNIQUE(story_id)
);

CREATE INDEX IF NOT EXISTS idx_story_series_parts_story
    ON story_series_parts(story_id, series_id);

INSERT OR IGNORE INTO sources(
    id,title,original_title,source_type,evidence_tier,institution,author_or_editor,language_id,publication_date,accessed_date,url,stable_url,catalogue_number,rights_status,source_perspective,community_or_lineage,collector_context,living_tradition,access_or_reuse_restrictions,community_permission_required,translation_status,verification_status,notes
) VALUES
('source.greek.odyssey_butler.gutenberg','Homer, The Odyssey, rendered into English prose (tr. Samuel Butler, 1900)','Ὀδύσσεια','HISTORICAL_TRANSLATION',3,'Project Gutenberg (eBook #1727)','Homer (Homeric tradition); translated by Samuel Butler','lang.en','1900','2026-10-24','https://www.gutenberg.org/ebooks/1727',NULL,'Books I–XXIV','Public-domain translation distributed by Project Gutenberg','English prose translation of the Homeric epic; the Greek text is registered separately as source.greek.odyssey.scaife',NULL,'Public web page',0,'Cite book numbers; publish independent retellings rather than the translation.',0,'English prose translation of the Greek','URL_SYNTAX_VALID','Project Gutenberg eBook #1727 (Butler''s prose Odyssey) matched through public search-index metadata on 2026-10-24.');

INSERT OR IGNORE INTO entities(
    id,canonical_name,name_zh,original_name,transliteration,primary_type,primary_civilization_id,historical_period,description,research_status,evidence_status,record_version,metadata_json,created_at,updated_at
) VALUES
('deity.chinese.guanyin_xiyouji','Guanyin (Journey to the West)','观音菩萨（《西游记》）','觀世音菩薩','Guānshìyīn Púsà','DEITY','civ.chinese_folk','Ming novel portrayal','The bodhisattva Guanyin as a character of Journey to the West, who seeks the scripture pilgrim, recruits his disciples and gives the golden fillet; kept separate from Buddhist doctrine and from the history of Avalokiteśvara devotion.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('hero.chinese.tang_sanzang','Tang Sanzang (Xuanzang of the novel)','唐三藏（玄奘）','唐三藏','Táng Sānzàng','HERO','civ.chinese_folk','Ming novel portrayal','The scripture pilgrim of Journey to the West, born Chen Jiangliu and reincarnated from the Buddha''s disciple Golden Cicada; the novel''s figure is kept separate from the historical monk Xuanzang (602–664).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('hero.chinese.zhu_bajie','Zhu Bajie','猪八戒','豬八戒','Zhū Bājiè','HERO','civ.chinese_folk','Ming novel portrayal','Former Marshal of the Heavenly Canopy, reborn with a pig''s face after offending the moon goddess; Tang Sanzang''s second disciple in Journey to the West.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('hero.chinese.sha_wujing','Sha Wujing','沙悟净','沙悟淨','Shā Wùjìng','HERO','civ.chinese_folk','Ming novel portrayal','Former Curtain-Raising General banished to the Flowing Sands River for breaking a crystal cup; Tang Sanzang''s third disciple in Journey to the West.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('dragon.chinese.white_dragon_horse','White Dragon Horse','白龙马','白龍馬','Bái Lóngmǎ','DRAGON','civ.chinese_folk',NULL,'Third prince of the Dragon King of the Western Sea, saved by Guanyin and turned into the horse that carries Tang Sanzang in Journey to the West.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('dragon.chinese.jinghe_dragon_king','Dragon King of the Jing River','泾河龙王','涇河龍王','Jīnghé Lóngwáng','DRAGON','civ.chinese_folk',NULL,'Dragon king who alters heaven''s rain decree to win a bet with the fortune-teller Yuan Shoucheng and is beheaded in Wei Zheng''s dream (Journey to the West ch. 10).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('historical.chinese.tang_taizong','Emperor Taizong of Tang','唐太宗','唐太宗','Táng Tàizōng','HISTORICAL_FIGURE','civ.chinese_folk','r. 626–649; Ming novel portrayal','Second Tang emperor (r. 626–649). Journey to the West portrays him visiting the underworld and sending Tang Sanzang west; those episodes belong to the novel, not to history.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('artifact.chinese.golden_fillet','Golden fillet (jingu)','紧箍','緊箍兒','jǐngū''ér','SACRED_OBJECT','civ.chinese_folk',NULL,'Gold band given by the Buddha to Guanyin and placed on Sun Wukong''s head; Tang Sanzang''s Tight-Fillet Spell makes it tighten (Journey to the West ch. 8, 14).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('artifact.chinese.brocade_cassock','Brocade cassock','锦襕袈裟','錦襴袈裟','jǐnlán jiāshā','SACRED_OBJECT','civ.chinese_folk',NULL,'Treasure cassock from the Buddha that Guanyin gives Tang Sanzang; stolen by the Black Bear Spirit and recovered by Sun Wukong (Journey to the West ch. 8, 12, 16–17).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('demon.chinese.black_bear_spirit','Black Bear Spirit','黑熊精','黑熊精','Hēixióng jīng','DEMON','civ.chinese_folk',NULL,'Bear demon of Black Wind Mountain who steals Tang Sanzang''s cassock and is subdued by Guanyin to guard her mountain (Journey to the West ch. 16–17).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('demon.chinese.baigujing','White Bone Demon (Lady White Bone)','白骨夫人（白骨精）','白骨夫人','Báigǔ Fūrén','DEMON','civ.chinese_folk',NULL,'Corpse demon of White Tiger Ridge who three times takes human form to trick Tang Sanzang and is killed by Sun Wukong, leading to his banishment (Journey to the West ch. 27).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('demon.chinese.huangpao','Yellow Robe Demon (Kui Wolf Star)','黄袍怪（奎木狼）','黃袍怪','Huángpáo guài','DEMON','civ.chinese_folk',NULL,'Demon of the Moon-Wave Cave who holds the princess of Baoxiang for thirteen years and turns Tang Sanzang into a tiger; revealed as the Kui Wolf constellation spirit (Journey to the West ch. 28–31).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('demon.chinese.six_eared_macaque','Six-Eared Macaque','六耳猕猴','六耳獼猴','Liù''ěr míhóu','DEMON','civ.chinese_folk',NULL,'Monkey who impersonates Sun Wukong so perfectly that no god can tell them apart until the Buddha names him and Wukong kills him (Journey to the West ch. 57–58).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('demon.chinese.niumowang','Bull Demon King','牛魔王','牛魔王','Niú Mówáng','DEMON','civ.chinese_folk',NULL,'Demon king and former sworn brother of Sun Wukong, husband of the Rākṣasī and father of Red Boy, who fights Wukong over the plantain fan until heaven''s forces subdue him (Journey to the West ch. 59–61).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('demon.chinese.tieshan_gongzhu','Princess Iron Fan (Rākṣasī)','铁扇公主（罗刹女）','鐵扇公主','Tiěshàn Gōngzhǔ','DEMON','civ.chinese_folk',NULL,'Wife of the Bull Demon King and mother of Red Boy, keeper of the plantain fan that puts out the Flaming Mountains (Journey to the West ch. 59–61).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('artifact.chinese.bajiao_shan','Plantain fan','芭蕉扇','芭蕉扇','bājiāo shàn','SACRED_OBJECT','civ.chinese_folk',NULL,'Fan of Princess Iron Fan: one wave puts out the fire, a second brings wind, a third brings rain; it can blow a man fifty thousand li (Journey to the West ch. 59–61).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('place.chinese.flaming_mountains_xiyouji','Flaming Mountains (Journey to the West)','火焰山（《西游记》）','火焰山','Huǒyàn Shān','MYTHICAL_PLACE','civ.chinese_folk',NULL,'Eight hundred li of fire on the pilgrims'' road, said in the novel to come from bricks of Laozi''s furnace kicked over by Sun Wukong; distinct from the real Flaming Mountains of Turpan.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('hero.indian.vishvamitra','Viśvāmitra','众友仙人','विश्वामित्र','Viśvāmitra','HERO','civ.hindu','Vālmīki Rāmāyaṇa','King turned brahmin sage who takes the young Rāma and Lakṣmaṇa to guard his sacrifice, gives Rāma the divine weapons and leads him to Mithilā.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('hero.indian.janaka','Janaka','遮那竭','जनक','Janaka','HERO','civ.hindu','Vālmīki Rāmāyaṇa','King of Mithilā who found Sītā in a ploughed furrow and promised her to whoever could string the bow of Śiva.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('hero.indian.kaikeyi','Kaikeyī','吉迦伊','कैकेयी','Kaikeyī','HERO','civ.hindu','Vālmīki Rāmāyaṇa','Queen of Daśaratha and mother of Bharata, who uses two old boons to have Rāma exiled for fourteen years.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('hero.indian.parashurama','Paraśurāma','持斧罗摩','परशुराम','Paraśurāma','HERO','civ.hindu','Vālmīki Rāmāyaṇa','Axe-bearing brahmin warrior, destroyer of kṣatriyas, who challenges Rāma after the breaking of Śiva''s bow and yields when Rāma strings the bow of Vishnu.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('hero.indian.ahalya','Ahalyā','阿诃厘耶','अहल्या','Ahalyā','HERO','civ.hindu','Vālmīki Rāmāyaṇa','Wife of the sage Gautama, cursed after Indra''s deception and released when Rāma enters the hermitage.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('hero.indian.sugriva','Sugrīva','须羯哩婆','सुग्रीव','Sugrīva','HERO','civ.hindu','Vālmīki Rāmāyaṇa','Vānara prince exiled by his brother Vālin, who allies with Rāma and becomes king of Kiṣkindhā.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('hero.indian.valin','Vālin','波林','वालिन्','Vālin','HERO','civ.hindu','Vālmīki Rāmāyaṇa','Vānara king of Kiṣkindhā, son of Indra, who seized his brother Sugrīva''s wife and is shot by Rāma from concealment.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('hero.indian.vibhishana','Vibhīṣaṇa','维毗沙那','विभीषण','Vibhīṣaṇa','HERO','civ.hindu','Vālmīki Rāmāyaṇa','Rāvaṇa''s righteous younger brother, who counsels the return of Sītā, takes refuge with Rāma and is crowned king of Laṅkā.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('creature.hindu.jatayu','Jaṭāyu','阇吒优私','जटायु','Jaṭāyu','DIVINE_BEAST','civ.hindu',NULL,'Aged vulture-king and friend of Daśaratha, who fights Rāvaṇa to save Sītā and dies telling Rāma what happened.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('demon.hindu.shurpanakha','Śūrpaṇakhā','首哩薄那迦','शूर्पणखा','Śūrpaṇakhā','DEMON','civ.hindu','Vālmīki Rāmāyaṇa','Rāvaṇa''s sister, whose mutilation by Lakṣmaṇa sets off the war with Khara and the abduction of Sītā.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('demon.hindu.maricha','Mārīca','摩哩遮','मारीच','Mārīca','DEMON','civ.hindu','Vālmīki Rāmāyaṇa','Rākṣasa hurled into the sea by Rāma''s arrow as a boy, later forced by Rāvaṇa to become the golden deer.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('demon.hindu.kumbhakarna','Kumbhakarṇa','鸠槃羯叻拿','कुम्भकर्ण','Kumbhakarṇa','DEMON','civ.hindu','Vālmīki Rāmāyaṇa','Rāvaṇa''s giant brother who sleeps for months at a time, is woken for the war and slain by Rāma.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('demon.hindu.indrajit','Indrajit (Meghanāda)','因陀罗耆','इन्द्रजित्','Indrajit (Meghanāda)','DEMON','civ.hindu','Vālmīki Rāmāyaṇa','Rāvaṇa''s eldest son, who fights unseen from the clouds, binds Rāma and Lakṣmaṇa with serpent arrows and is slain by Lakṣmaṇa.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('deity.hindu.ganga','Gaṅgā','恒河女神','गङ्गा','Gaṅgā','DEITY','civ.hindu',NULL,'River goddess whose descent from heaven, caught in Śiva''s hair and led down by Bhagīratha, is told to Rāma in the Bāla Kāṇḍa.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('deity.hindu.agni','Agni','阿耆尼（火神）','अग्नि','Agni','DEITY','civ.hindu',NULL,'God of fire, who in the Yuddha Kāṇḍa rises from the pyre with Sītā unharmed and declares her pure; kept separate from the element entry for fire.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('hero.greek.odysseus','Odysseus','奥德修斯','Ὀδυσσεύς','Odysseus','HERO','civ.greek','Homeric epic (c. 8th–7th century BCE)','King of Ithaca and hero of the Odyssey, who wanders ten years after the fall of Troy before returning home to defeat his wife''s suitors.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('hero.greek.penelope','Penelope','珀涅罗珀','Πηνελόπεια','Penelope','HERO','civ.greek','Homeric epic (c. 8th–7th century BCE)','Wife of Odysseus, who keeps the suitors at bay for years with the trick of the unwoven shroud and tests her returned husband with the secret of their bed.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('hero.greek.telemachus','Telemachus','忒勒马科斯','Τηλέμαχος','Telemachus','HERO','civ.greek','Homeric epic (c. 8th–7th century BCE)','Son of Odysseus and Penelope, who sails in search of news of his father and fights beside him against the suitors.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('creature.greek.polyphemus','Polyphemus','波吕斐摩斯','Πολύφημος','Polyphemus','GIANT','civ.greek','Homeric epic (c. 8th–7th century BCE)','One-eyed Cyclops, son of Poseidon, who eats six of Odysseus''s men and is blinded by him (Odyssey 9).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('deity.greek.circe','Circe','喀耳刻','Κίρκη','Circe','DEITY','civ.greek','Homeric epic (c. 8th–7th century BCE)','Goddess and enchantress of the island Aeaea who turns Odysseus''s men into swine, then helps him and sends him to the underworld (Odyssey 10–12).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('deity.greek.calypso','Calypso','卡吕普索','Καλυψώ','Calypso','DEITY','civ.greek','Homeric epic (c. 8th–7th century BCE)','Nymph-goddess of the island Ogygia who keeps Odysseus seven years and offers him immortality, until Hermes brings Zeus''s order to let him go (Odyssey 5).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('creature.greek.scylla','Scylla','斯库拉','Σκύλλα','Scylla','MONSTER','civ.greek','Homeric epic (c. 8th–7th century BCE)','Six-headed monster in a sea cliff who snatches six of Odysseus''s men from his ship (Odyssey 12).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('creature.greek.charybdis','Charybdis','卡律布狄斯','Χάρυβδις','Charybdis','MONSTER','civ.greek','Homeric epic (c. 8th–7th century BCE)','Whirlpool beneath a fig tree that swallows and spews out the sea three times a day (Odyssey 12).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('creature.greek.sirens','Sirens','塞壬','Σειρῆνες','Sirens','MONSTER','civ.greek','Homeric epic (c. 8th–7th century BCE)','Singers on a meadow strewn with bones whose song lures sailors to death; Odysseus hears them bound to his mast (Odyssey 12).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('place.greek.ithaca_homeric','Ithaca (Homeric)','伊塔卡（荷马史诗）','Ἰθάκη','Ithaca','MYTHICAL_PLACE','civ.greek',NULL,'Odysseus''s island kingdom as described in the Odyssey; its identification with the modern island of Ithaki is a long scholarly debate.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('event.greek.return_of_odysseus','The return of Odysseus (Odyssey)','奥德修斯归家（《奥德赛》）',NULL,NULL,'EVENT','civ.greek',NULL,'Odysseus''s ten-year wandering after Troy and his return to Ithaca to defeat the suitors, as told in the Odyssey''s twenty-four books.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('hero.greek.laertes','Laertes','拉厄耳忒斯','Λαέρτης','Laertes','HERO','civ.greek','Homeric epic (c. 8th–7th century BCE)','Aged father of Odysseus who lives in grief on his farm while the suitors occupy the palace, and fights beside his son and grandson at the Odyssey''s close.','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('person.greek.eumaeus','Eumaeus','欧迈俄斯','Εὔμαιος','Eumaeus','PERSON','civ.greek','Homeric epic (c. 8th–7th century BCE)','Loyal swineherd of Odysseus, a king''s son kidnapped in childhood, who shelters his disguised master and fights beside him against the suitors (Odyssey 14–22).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('person.greek.eurycleia','Eurycleia','欧律克勒亚','Εὐρύκλεια','Eurycleia','PERSON','civ.greek','Homeric epic (c. 8th–7th century BCE)','Old nurse of Odysseus who recognises him by the boar-tusk scar on his thigh as she washes his feet (Odyssey 19).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('person.greek.antinous','Antinous','安提诺俄斯','Ἀντίνοος','Antinous','PERSON','civ.greek','Homeric epic (c. 8th–7th century BCE)','Most arrogant of Penelope''s suitors, who plots to ambush Telemachus and is the first to die when Odysseus strings his bow (Odyssey 1–22).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('weapon.greek.bow_of_odysseus','Bow of Odysseus','奥德修斯的弓',NULL,NULL,'WEAPON','civ.greek',NULL,'Great bow given to Odysseus by Iphitus, left at home when he sailed for Troy; no suitor can string it, and Odysseus shoots through twelve axes with it (Odyssey 21).','PARTIAL','SOURCE_BACKED',1,'{}','2026-10-24T01:00:00Z','2026-10-24T01:00:00Z');

