INSERT OR IGNORE INTO creature_profiles(
    entity_id,creature_class,appearance_json,abilities_json,weaknesses_json,habitat_summary,origin_summary,fate_summary
) VALUES
('dragon.chinese.white_dragon_horse','DRAGON_PRINCE','{}','["takes the form of a white horse"]','[]','Eagle Grief Gorge until the pilgrimage','Third son of the Dragon King of the Western Sea, condemned for burning a pearl.','Carries Tang Sanzang to the West.'),
('dragon.chinese.jinghe_dragon_king','DRAGON_KING','{}','["brings rain at heaven''s command"]','[]','The Jing River near Chang''an','River dragon king in the novel.','Beheaded in Wei Zheng''s dream for disobeying heaven''s decree.'),
('demon.chinese.black_bear_spirit','BEAR_DEMON','{}','["black wind", "black-tasselled spear"]','[]','Black Wind Cave on Black Wind Mountain','A black bear that attained powers.','Becomes the guardian of Guanyin''s Potalaka mountain.'),
('demon.chinese.baigujing','CORPSE_DEMON','{}','["takes human forms", "escapes by leaving a false corpse"]','[]','White Tiger Ridge','A heap of bones that became a demon.','Killed by Sun Wukong''s third blow; a pile of bones inscribed ''Lady White Bone''.'),
('demon.chinese.huangpao','STAR_SPIRIT_DEMON','{}','["transformations", "turns people into beasts"]','[]','Moon-Wave Cave on Bowl Mountain','The Kui constellation spirit, one of the twenty-eight lunar mansions, who came down for love of a palace maid.','Recalled to heaven and set to tend Laozi''s furnace.'),
('demon.chinese.six_eared_macaque','MONKEY_DEMON','{}','["hears sounds from a thousand li", "knows past and future", "every power of Sun Wukong"]','[]','Water Curtain Cave (usurped)','One of the four monkeys outside the ten categories of beings, as the Buddha explains.','Killed by Sun Wukong under the Buddha''s golden bowl.'),
('demon.chinese.niumowang','BULL_DEMON','{}','["seventy-two transformations", "becomes a giant white bull"]','[]','Cloud-Touching Cave on Thunder Mountain','Demon king, once sworn brother of the Monkey King.','Subdued by Nezha and heaven''s guardians and taken to the Buddha.'),
('demon.chinese.tieshan_gongzhu','RAKSHASI','{}','["keeps the plantain fan", "twin blue swords"]','[]','Plantain Cave on Kingfisher Cloud Mountain','Wife of the Bull Demon King.','Gives up the fan and withdraws to self-cultivation.'),
('creature.hindu.jatayu','VULTURE_KING','{}','["speech", "flight"]','[]','Pañcavaṭī forest','Son of Aruṇa, brother of Sampāti.','Mortally wounded by Rāvaṇa; cremated by Rāma.'),
('demon.hindu.shurpanakha','RAKSHASI','{}','["changes shape at will"]','[]','Daṇḍaka forest','Sister of Rāvaṇa.','Flees to Laṅkā to rouse Rāvaṇa.'),
('demon.hindu.maricha','RAKSHASA','{}','["takes the form of a golden deer", "mimics voices"]','[]','A hermitage by the sea','Son of Tāṭakā.','Killed by Rāma while in the deer''s form.'),
('demon.hindu.kumbhakarna','GIANT_RAKSHASA','{}','["immense size and hunger"]','[]','Laṅkā','Brother of Rāvaṇa, cursed to long sleep.','Slain by Rāma''s arrows.'),
('demon.hindu.indrajit','RAKSHASA','{}','["invisibility in battle", "serpent arrows", "the weapon of Brahmā"]','[]','Laṅkā','Son of Rāvaṇa who once defeated Indra.','Slain by Lakṣmaṇa.'),
('creature.greek.polyphemus','CYCLOPS','{"eyes": 1}','["enormous strength"]','[]','A cave on the island of the Cyclopes','Son of Poseidon and the nymph Thoosa.','Blinded by Odysseus; his curse brings Poseidon''s anger.'),
('creature.greek.scylla','SEA_MONSTER','{"heads": 6, "feet": 12}','["snatches sailors from passing ships"]','[]','A cave high in a sea cliff','Immortal monster, as Circe describes her.','Remains in her cliff.'),
('creature.greek.charybdis','WHIRLPOOL_MONSTER','{}','["swallows the sea three times a day"]','[]','Beneath a fig tree opposite Scylla','Divine whirlpool of the strait.','Remains in the strait.'),
('creature.greek.sirens','ENCHANTING_SINGERS','{}','["a song that lures sailors to death"]','[]','A flowery meadow heaped with bones','Described by Circe; their number and form are not fixed in the Odyssey.','Unchanged; Odysseus passes them.');

INSERT OR IGNORE INTO artifact_profiles(
    entity_id,artifact_type,material_json,appearance_json,abilities_json,limitations_json,usage_conditions_json,creation_summary,fate_summary
) VALUES
('artifact.chinese.golden_fillet','FILLET','["gold"]','{}','["tightens when the Tight-Fillet Spell is recited"]','[]','[]','One of three fillets the Buddha gives Guanyin.','Worn by Sun Wukong until the pilgrimage ends.'),
('artifact.chinese.brocade_cassock','GARMENT','["brocade", "pearls"]','{}','["spares its wearer rebirth (as the novel says)"]','[]','[]','From the Buddha''s treasures on Spirit Mountain.','Worn by Tang Sanzang on the pilgrimage.'),
('artifact.chinese.bajiao_shan','FAN','["plantain leaf (as the novel describes)"]','{}','["extinguishes fire", "raises wind and rain", "shrinks to the size of an apricot leaf"]','[]','[]','A treasure of the Rākṣasī, formed since the beginning of the world, as she says.','Returned to the Rākṣasī after the fire is put out.'),
('weapon.greek.bow_of_odysseus','BOW','["horn", "wood"]','{}','["only Odysseus can string it"]','[]','[]','A guest-gift from Iphitus, son of Eurytus, when the two met in Messene.','Used by Odysseus to win the contest and to kill the suitors.');

INSERT OR IGNORE INTO place_profiles(
    entity_id,place_type,ancient_name,modern_name,country_code,latitude,longitude,date_range,builders,architecture_summary,excavation_summary,major_finds_summary,unesco_status,reality_status,evidence_grade
) VALUES
('place.chinese.flaming_mountains_xiyouji','MYTHIC_MOUNTAIN','火焰山',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'LATER_LEGEND','TEXTUAL'),
('place.greek.ithaca_homeric','HOMERIC_ISLAND','Ithaca','Ithaki (identification debated)','GR',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'MIXED','TEXTUAL');

INSERT OR IGNORE INTO myth_event_profiles(
    entity_id,event_type,time_layer,cause_summary,process_summary,result_summary,symbolism_summary
) VALUES
('event.greek.return_of_odysseus','HEROIC_HOMECOMING','Ten years after the fall of Troy (in the epic''s chronology)','Poseidon''s anger after the blinding of Polyphemus; the suitors besiege Penelope.','Wanderings from the Cicones to Calypso''s island; return in disguise; the contest of the bow.','The suitors are killed, Odysseus is reunited with Penelope and Laertes, and Athena imposes peace.','The Odyssey''s own book divisions are later (Hellenistic); the retelling follows them for location only.');

INSERT OR IGNORE INTO claims(
    id,subject_id,predicate,object_entity_id,object_literal,object_datatype,statement,variant_group,claim_status,confidence,confidence_level,review_status,assertion_scope,knowledge_layer,tradition_scope,temporal_scope,research_notes,created_at
) VALUES
('claim.v0330.xyj_origins.01','deity.chinese.rulai_xiyouji','NARRATIVE_ACTION',NULL,'offers the three baskets of scripture to the east','string','At the Ullambana feast the Buddha of the novel offers three baskets of scripture (35 works, 15,144 scrolls) for the eastern land and asks for a pilgrim to fetch them; Guanyin volunteers to find one.','v0330.xyj_origins','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_origins.02','deity.chinese.guanyin_xiyouji','NARRATIVE_ACTION',NULL,'receives the cassock, staff and three fillets','string','The Buddha gives Guanyin a brocade cassock, a nine-ringed staff and three fillets with spells for disciples who disobey; she sets out east with Huian (Muzha).','v0330.xyj_origins','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_origins.03','hero.chinese.sha_wujing','NARRATIVE_ACTION',NULL,'is named Sha Wujing and told to wait for the pilgrim','string','Guanyin enlists the banished Curtain-Raising General at the Flowing Sands River as Sha Wujing and the banished Marshal of the Heavenly Canopy at Fuling Mountain as Zhu Wuneng, to wait for the pilgrim.','v0330.xyj_origins','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_origins.04','deity.chinese.guanyin_xiyouji','NARRATIVE_ACTION',NULL,'spares the jade dragon and promises Wukong release','string','Guanyin obtains a pardon for the condemned jade dragon prince to serve as the pilgrim''s mount and promises Sun Wukong release if he becomes the pilgrim''s disciple.','v0330.xyj_origins','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_origins.05','hero.chinese.tang_sanzang','NARRATIVE_CONDITION',NULL,'father Chen Guangrui releases a golden carp','string','In the novel''s ninth chapter Tang Sanzang''s father Chen Guangrui wins the examination, marries Yin Wenjiao through an embroidered ball and releases a blinking golden carp into the Hong River on his way to his post.','v0330.xyj_origins','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_origins.06','hero.chinese.tang_sanzang','NARRATIVE_CONDITION',NULL,'father murdered at the Hong River crossing','string','The boatman Liu Hong murders Chen Guangrui at the Hong River crossing and takes his post and his wife; the river''s dragon king, the carp he had freed, preserves his body with a pearl.','v0330.xyj_origins','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_origins.07','hero.chinese.tang_sanzang','NARRATIVE_ACTION',NULL,'set adrift on a plank and raised at Jinshan Monastery','string','As a newborn, Tang Sanzang is set adrift on a plank with his mother''s letter in blood and the tip of his left little toe bitten off as a mark; Abbot Faming of Jinshan Monastery raises him as Jiangliu.','v0330.xyj_origins','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_origins.08','hero.chinese.tang_sanzang','NARRATIVE_ACTION',NULL,'finds his mother and avenges his father','string','Ordained as Xuanzang at eighteen, he learns his origin from the blood letter, finds his mother, heals his blind grandmother, and his grandfather''s troops capture Liu Hong; Chen Guangrui is restored to life by the river''s dragon king.','v0330.xyj_origins','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_origins.09','dragon.chinese.jinghe_dragon_king','NARRATIVE_ACTION',NULL,'goes in disguise to test the fortune-teller','string','Told by a yaksha that the fortune-teller Yuan Shoucheng guides the fisherman Zhang Shao''s nets every day, the Dragon King of the Jing River goes into Chang''an disguised as a white-robed scholar to test him.','v0330.xyj_origins','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_origins.10','dragon.chinese.jinghe_dragon_king','NARRATIVE_ACTION',NULL,'alters heaven''s rain decree to win a bet','string','After betting against Yuan Shoucheng''s forecast and then receiving a decree that matches it exactly, the Jing River dragon king delays the rain and withholds three inches and eight drops to win.','v0330.xyj_origins','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_origins.11','dragon.chinese.jinghe_dragon_king','NARRATIVE_ACTION',NULL,'is beheaded by Wei Zheng in a dream','string','Though Emperor Taizong keeps Wei Zheng at chess to save him, the Jing River dragon king is beheaded at noon by Wei Zheng in a dream, and his head falls from the sky.','v0330.xyj_origins','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_origins.12','historical.chinese.tang_taizong','NARRATIVE_ACTION',NULL,'dies after the dragon''s ghost haunts him','string','In the novel the beheaded dragon''s ghost haunts Emperor Taizong; Qin Shubao and Yuchi Jingde guard his gate and become the door gods, and Taizong dies carrying Wei Zheng''s letter to the underworld judge Cui Jue.','v0330.xyj_origins','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_origins.13','historical.chinese.tang_taizong','NARRATIVE_ACTION',NULL,'visits the underworld and returns to life','string','In the novel''s underworld the judge Cui Jue changes Taizong''s term in the register from the thirteenth to the thirty-third year; the emperor pays the wronged ghosts with a borrowed treasury, promises a mass for the dead and returns to life.','v0330.xyj_origins','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_origins.14','historical.chinese.tang_taizong','NARRATIVE_ACTION',NULL,'sends Liu Quan''s melons and repays Xiang Liang','string','In the novel Liu Quan dies to deliver Taizong''s melons to the underworld; his dead wife Li Cuilian returns in the body of the emperor''s sister, and the emperor builds the Xiangguo Monastery for Xiang Liang.','v0330.xyj_origins','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_origins.15','deity.chinese.guanyin_xiyouji','NARRATIVE_ACTION',NULL,'gives the cassock and staff for Xuanzang','string','Disguised as a scabby monk, Guanyin offers the Buddha''s cassock and staff for sale in Chang''an and then gives them free to Emperor Taizong for Xuanzang, chosen to lead the great mass for the dead.','v0330.xyj_origins','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_origins.16','deity.chinese.guanyin_xiyouji','NARRATIVE_ACTION',NULL,'reveals her true form at the great mass','string','At the great mass Guanyin interrupts Xuanzang''s preaching of the Lesser Vehicle, announces the Great Vehicle scriptures at Thunderclap Monastery in the west and reveals her true form on a cloud.','v0330.xyj_origins','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_origins.17','hero.chinese.tang_sanzang','NARRATIVE_ACTION',NULL,'sets out west as Sanzang','string','Xuanzang volunteers to fetch the scriptures; Emperor Taizong makes him his sworn brother, names him Sanzang and sends him west with a pinch of home soil in his wine.','v0330.xyj_origins','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_gather.01','hero.chinese.tang_sanzang','NARRATIVE_ACTION',NULL,'loses his attendants and is freed by the planet Venus','string','On Double Fork Ridge Tang Sanzang falls into a demons'' pit where the tiger spirit General Yin and his guests eat his two attendants; the planet Venus releases him at dawn.','v0330.xyj_gather','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_gather.02','hero.chinese.tang_sanzang','NARRATIVE_ACTION',NULL,'is sheltered by the hunter Liu Boqin','string','The hunter Liu Boqin rescues Tang Sanzang from a tiger and takes him home; Sanzang''s sutra chanting frees Boqin''s dead father for rebirth, and Boqin escorts him to the Mountain of Two Frontiers.','v0330.xyj_gather','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_gather.03','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'is freed from the Mountain of Two Frontiers','string','Tang Sanzang lifts the Buddha''s six-syllable seal from the Mountain of Two Frontiers, and Sun Wukong breaks out after five hundred years and kneels before him.','v0330.xyj_gather','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_gather.04','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'slays the six robbers and leaves in anger','string','Named Pilgrim Sun, Sun Wukong kills a tiger for its skin and slays six robbers named for the six senses; scolded by Tang Sanzang for killing, he leaves in anger.','v0330.xyj_gather','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_gather.05','deity.chinese.guanyin_xiyouji','NARRATIVE_ACTION','artifact.chinese.golden_fillet',NULL,NULL,'Disguised as an old woman, Guanyin gives Tang Sanzang a cap with a golden band and the Tight-Fillet Spell; when Sun Wukong puts it on, the band takes root and the spell brings him to submission.','v0330.xyj_gather','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_gather.06','dragon.chinese.white_dragon_horse','NARRATIVE_ACTION',NULL,'is turned into the White Dragon Horse','string','At Eagle Grief Gorge the jade dragon prince swallows Tang Sanzang''s horse; Guanyin, called by the guardian spirits, turns him into the White Dragon Horse and gives Sun Wukong three life-saving hairs.','v0330.xyj_gather','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_gather.07','hero.chinese.sun_wukong','NARRATIVE_ACTION','artifact.chinese.brocade_cassock',NULL,NULL,'When the greedy abbot of a Guanyin Chan monastery tries to burn the pilgrims for their cassock, Sun Wukong shields his master with a borrowed fire-proof cover and fans the fire, during which a demon from Black Wind Mountain steals the cassock.','v0330.xyj_gather','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_gather.08','demon.chinese.black_bear_spirit','NARRATIVE_ACTION',NULL,'keeps the stolen cassock for a robe feast','string','The Black Bear Spirit of Black Wind Mountain keeps the stolen cassock for a birthday ''Buddha-robe feast'' and holds off Sun Wukong, who goes to ask Guanyin for help.','v0330.xyj_gather','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_gather.09','deity.chinese.guanyin_xiyouji','NARRATIVE_ACTION','demon.chinese.black_bear_spirit',NULL,NULL,'Guanyin takes the form of the wolf Taoist Lingxuzi and offers Sun Wukong disguised as an elixir pill to the Black Bear Spirit, then subdues the bear with a fillet and makes him her mountain guardian.','v0330.xyj_gather','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_gather.10','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'confronts the pig-faced son-in-law at Gao Village','string','At Gao Village Sun Wukong takes the form of the daughter Cuilan to confront her pig-faced husband, who flees to Fuling Mountain when he recognises the Great Sage.','v0330.xyj_gather','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_gather.11','hero.chinese.zhu_bajie','NARRATIVE_ACTION',NULL,'joins Tang Sanzang and is named Bajie','string','At the Cloud-Ladder Cave the pig-faced monster submits on hearing of the scripture pilgrimage, burns his cave and becomes Tang Sanzang''s disciple, who names him Bajie.','v0330.xyj_gather','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_gather.12','hero.chinese.tang_sanzang','NARRATIVE_ACTION',NULL,'receives the Heart Sutra from the Crow''s Nest Chan master','string','On Pagoda Mountain the Crow''s Nest Chan master teaches Tang Sanzang the Heart Sutra of fifty-four lines and 270 characters, which he memorises at a single hearing.','v0330.xyj_gather','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_gather.13','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'has his eyes injured by the Samādhi wind','string','At Yellow Wind Ridge the Tiger Vanguard seizes Tang Sanzang, and the Great King of the Yellow Wind blows a Samādhi wind that scatters Sun Wukong''s clones and injures his fiery golden eyes.','v0330.xyj_gather','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_gather.14','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'brings Lingji Bodhisattva to subdue the wind demon','string','Healed by the guardian spirits'' ointment and directed by the planet Venus, Sun Wukong brings Lingji Bodhisattva, whose flying-dragon staff pins the Yellow Wind demon — a yellow marten that had stolen lamp oil on Spirit Mountain.','v0330.xyj_gather','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_gather.15','hero.chinese.zhu_bajie','NARRATIVE_ACTION',NULL,'fights the demon of the Flowing Sands River','string','At the Flowing Sands River Zhu Bajie fights the red-haired demon in the water while Sun Wukong waits on the bank; when the demon will not come ashore, Wukong goes to ask Guanyin for help.','v0330.xyj_gather','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_gather.16','hero.chinese.sha_wujing','NARRATIVE_ACTION',NULL,'ferries the master across on a raft of nine skulls','string','Called by name by Muzha, Sha Wujing submits to Tang Sanzang and ferries him across the Flowing Sands River on a raft of his nine skulls with Guanyin''s gourd at the centre; the four pilgrims are now together.','v0330.xyj_gather','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_white_bone.01','demon.chinese.baigujing','NARRATIVE_ACTION',NULL,'covets Tang Sanzang''s flesh on White Tiger Ridge','string','On White Tiger Ridge, while Sun Wukong is away picking peaches, the White Bone Demon sees Tang Sanzang and resolves to trick him, believing that a bite of his flesh gives eternal life.','v0330.xyj_white_bone','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_white_bone.02','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'strikes the demon disguised as a village girl','string','Sun Wukong strikes the White Bone Demon disguised as a village girl offering food; she escapes leaving a false corpse, and when Zhu Bajie accuses Wukong of murder, Tang Sanzang recites the Tight-Fillet Spell.','v0330.xyj_white_bone','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_white_bone.03','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'strikes the demon disguised as an old woman','string','When the White Bone Demon returns as an eighty-year-old woman seeking her daughter, Sun Wukong strikes again; Tang Sanzang recites the spell twenty times but keeps him because there is no spell to loosen the fillet.','v0330.xyj_white_bone','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_white_bone.04','hero.chinese.sun_wukong','NARRATIVE_ACTION','demon.chinese.baigujing',NULL,NULL,'With the local gods standing witness so that she cannot escape, Sun Wukong kills the White Bone Demon disguised as an old man; she is revealed as a pile of bones inscribed ''Lady White Bone''.','v0330.xyj_white_bone','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_white_bone.05','hero.chinese.tang_sanzang','NARRATIVE_ACTION',NULL,'banishes Sun Wukong with a written dismissal','string','Persuaded by Zhu Bajie that the bones are a trick, Tang Sanzang writes a letter of dismissal and banishes Sun Wukong, who bows to him from four sides with three magic copies and returns in tears to the Mountain of Flowers and Fruit.','v0330.xyj_white_bone','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_white_bone.06','hero.chinese.sun_wukong','NARRATIVE_ACTION','place.chinese.huaguo_shan',NULL,NULL,'Back on the burned Mountain of Flowers and Fruit, Sun Wukong destroys the hunters who prey on his monkeys with a gale of stones, restores the mountain and raises the banner of the Great Sage again.','v0330.xyj_white_bone','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_white_bone.07','demon.chinese.huangpao','NARRATIVE_ACTION','hero.chinese.tang_sanzang',NULL,NULL,'With Sun Wukong gone, Tang Sanzang wanders into a pagoda in the Black Pine Forest and is seized by the Yellow Robe Demon of the Moon-Wave Cave, who fights Zhu Bajie and Sha Wujing to a standstill.','v0330.xyj_white_bone','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_white_bone.08','hero.chinese.tang_sanzang','NARRATIVE_ACTION',NULL,'carries the captive princess''s letter to Baoxiang','string','Princess Baihuaxiu of Baoxiang, held by the Yellow Robe Demon for thirteen years, persuades him to free Tang Sanzang and gives Sanzang a letter for her father.','v0330.xyj_white_bone','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_white_bone.09','hero.chinese.zhu_bajie','NARRATIVE_ACTION',NULL,'deserts the fight and leaves Sha Wujing to be captured','string','Sent by the king of Baoxiang to rescue his daughter, Zhu Bajie boasts and grows huge at court, but in the fight with the Yellow Robe Demon he hides in a thicket, and Sha Wujing is captured.','v0330.xyj_white_bone','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_white_bone.10','demon.chinese.huangpao','NARRATIVE_ACTION',NULL,'turns Tang Sanzang into a tiger','string','Posing as the princess''s rescuer and husband at the court of Baoxiang, the Yellow Robe Demon turns Tang Sanzang into a tiger with a spell and, drunk at the palace feast, eats a palace maid.','v0330.xyj_white_bone','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_white_bone.11','dragon.chinese.white_dragon_horse','NARRATIVE_ACTION',NULL,'attacks the demon disguised as a palace maid','string','The White Dragon Horse takes the form of a palace maid, attacks the Yellow Robe Demon during a sword dance, is wounded by a candlestick and then urges Zhu Bajie to fetch Sun Wukong.','v0330.xyj_white_bone','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_white_bone.12','hero.chinese.zhu_bajie','NARRATIVE_ACTION','hero.chinese.sun_wukong',NULL,NULL,'At the Mountain of Flowers and Fruit Zhu Bajie, rebuffed at first, goads Sun Wukong into returning by claiming the Yellow Robe Demon has insulted him; Wukong washes in the sea before going back to his master.','v0330.xyj_white_bone','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_white_bone.13','hero.chinese.sun_wukong','NARRATIVE_ACTION','demon.chinese.huangpao',NULL,NULL,'Disguised as Princess Baihuaxiu, Sun Wukong tricks the Yellow Robe Demon into giving up his inner elixir, swallows it and fights him until the demon vanishes.','v0330.xyj_white_bone','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_white_bone.14','demon.chinese.huangpao','NARRATIVE_ACTION',NULL,'is revealed as the Kui Wolf star and recalled to heaven','string','Checked against heaven''s rolls, the Yellow Robe Demon is found to be the missing Kui Wolf star, who confesses that he came down to keep a promise to a jade maiden reborn as the princess and is sent to tend Laozi''s furnace.','v0330.xyj_white_bone','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_white_bone.15','hero.chinese.sun_wukong','NARRATIVE_ACTION','hero.chinese.tang_sanzang',NULL,NULL,'Sun Wukong breaks the spell on the caged tiger with a spray of water, restoring Tang Sanzang to human form; master and disciple are reconciled and the four pilgrims leave Baoxiang together.','v0330.xyj_white_bone','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_two_monkeys.01','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'kills the two highwaymen chiefs','string','When highwaymen tie Tang Sanzang to a tree, Sun Wukong tricks them into freeing him and kills their two chiefs; Sanzang buries them and prays that their ghosts blame Wukong alone.','v0330.xyj_two_monkeys','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_two_monkeys.02','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'kills the robbers and beheads Old Yang''s son','string','When the son of their host Old Yang leads the robbers in pursuit, Sun Wukong kills the gang and brings the son''s severed head to Tang Sanzang.','v0330.xyj_two_monkeys','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_two_monkeys.03','hero.chinese.tang_sanzang','NARRATIVE_ACTION','hero.chinese.sun_wukong',NULL,NULL,'Horrified by the killings and the severed head of their host''s son, Tang Sanzang recites the Tight-Fillet Spell repeatedly and drives Sun Wukong away.','v0330.xyj_two_monkeys','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_two_monkeys.04','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'weeps before Guanyin at Potalaka','string','Driven away a second time when he tries to return, Sun Wukong flies to Guanyin at Potalaka and weeps before her; she has no spell to loosen the fillet and keeps him with her.','v0330.xyj_two_monkeys','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_two_monkeys.05','demon.chinese.six_eared_macaque','NARRATIVE_ACTION','hero.chinese.tang_sanzang',NULL,NULL,'In Sun Wukong''s form, the false Monkey King offers Tang Sanzang water, is refused, knocks him senseless with an iron rod and flies off with the baggage and travel rescript.','v0330.xyj_two_monkeys','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_two_monkeys.06','hero.chinese.sha_wujing','NARRATIVE_ACTION',NULL,'kills the false Sha Wujing on the Mountain of Flowers and Fruit','string','At the Mountain of Flowers and Fruit Sha Wujing finds the false Wukong reading the stolen travel rescript with a fake pilgrim party of monkeys; he kills the false Sha Wujing and flies to Guanyin.','v0330.xyj_two_monkeys','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_two_monkeys.07','deity.chinese.guanyin_xiyouji','NARRATIVE_ACTION',NULL,'testifies that the real Wukong has been with her four days','string','When Sha Wujing reaches Potalaka and finds Sun Wukong there, Guanyin testifies that Wukong has been with her for four days and sends the two of them to the Mountain of Flowers and Fruit.','v0330.xyj_two_monkeys','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_two_monkeys.08','demon.chinese.six_eared_macaque','NARRATIVE_ACTION','hero.chinese.sun_wukong',NULL,NULL,'On the Mountain of Flowers and Fruit the false Monkey King, identical in every detail, fights the real Sun Wukong for hundreds of rounds while Sha Wujing cannot tell them apart.','v0330.xyj_two_monkeys','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_two_monkeys.09','deity.chinese.jade_emperor','NARRATIVE_ACTION',NULL,'cannot tell the two Wukongs apart with the demon-revealing mirror','string','Neither Guanyin''s Tight-Fillet Spell, which pains both Wukongs alike, nor the demon-revealing mirror that Li Jing holds up before the Jade Emperor can tell the real Sun Wukong from the false.','v0330.xyj_two_monkeys','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_two_monkeys.10','hero.chinese.tang_sanzang','NARRATIVE_ACTION',NULL,'recites the spell but cannot tell the two Wukongs apart','string','Tang Sanzang''s Tight-Fillet Spell pains both Wukongs alike, and in the underworld the registers of the dead show no entry for either, since Wukong had long ago struck out the monkeys'' names.','v0330.xyj_two_monkeys','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_two_monkeys.11','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'is sent to the Buddha after Diting will not speak','string','Kṣitigarbha''s beast Diting hears the truth about the two Wukongs but will not name the false one to his face, and directs them to the Buddha because ''the Buddha''s law is boundless''.','v0330.xyj_two_monkeys','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_two_monkeys.12','deity.chinese.rulai_xiyouji','NARRATIVE_ACTION','demon.chinese.six_eared_macaque',NULL,NULL,'At Thunderclap Monastery the Buddha explains the four monkeys outside the ten categories of beings and names the false Wukong as the six-eared macaque, who hears and knows all things.','v0330.xyj_two_monkeys','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_two_monkeys.13','hero.chinese.sun_wukong','NARRATIVE_ACTION','demon.chinese.six_eared_macaque',NULL,NULL,'When the Buddha traps the six-eared macaque under his golden alms bowl, Sun Wukong kills him with one blow; Guanyin brings Wukong back to Tang Sanzang, who takes him back.','v0330.xyj_two_monkeys','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_fan.01','hero.chinese.tang_sanzang','NARRATIVE_ACTION','place.chinese.flaming_mountains_xiyouji',NULL,NULL,'In autumn the pilgrims reach a red farmhouse where an old man tells them the only road west crosses eight hundred li of fire at the Flaming Mountains.','v0330.xyj_fan','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_fan.02','artifact.chinese.bajiao_shan','DESCRIBED_AS',NULL,'one wave quenches the fire, two raise wind, three bring rain','string','The villagers by the Flaming Mountains tell Sun Wukong that the plantain fan of the Iron Fan Immortal puts out the fire with one wave, raises wind with a second and brings rain with a third.','v0330.xyj_fan','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_fan.03','demon.chinese.tieshan_gongzhu','NARRATIVE_ACTION','hero.chinese.sun_wukong',NULL,NULL,'Princess Iron Fan, blaming Sun Wukong for losing her son Red Boy, strikes his head a dozen times with her swords when he asks to borrow the plantain fan, without hurting him.','v0330.xyj_fan','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_fan.04','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'is fanned fifty thousand li and receives the wind-fixing pill','string','Fanned fifty thousand li to the Little Sumeru Mountain by the plantain fan, Sun Wukong receives Lingji Bodhisattva''s wind-fixing pill and returns to the Plantain Cave.','v0330.xyj_fan','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_fan.05','hero.chinese.sun_wukong','NARRATIVE_ACTION','demon.chinese.tieshan_gongzhu',NULL,NULL,'Unmoved by the fan thanks to the wind-fixing pill, Sun Wukong turns into an insect, is swallowed in Princess Iron Fan''s tea and torments her from inside until she hands over a fan.','v0330.xyj_fan','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_fan.06','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'discovers the fan is false','string','Fanning the Flaming Mountains with the fan he took, Sun Wukong only makes the fire rise a thousand fathoms and burns his own hair, for the Rākṣasī had given him a false fan.','v0330.xyj_fan','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_fan.07','place.chinese.flaming_mountains_xiyouji','ORIGIN_ACCOUNT',NULL,'formed from bricks of Laozi''s furnace kicked over by Sun Wukong','string','The earth god tells Sun Wukong that the Flaming Mountains came from bricks with live embers that fell when Wukong kicked over Laozi''s furnace five hundred years before.','v0330.xyj_fan','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_fan.08','demon.chinese.niumowang','NARRATIVE_ACTION','hero.chinese.sun_wukong',NULL,NULL,'After Sun Wukong frightens the Jade-Faced Princess on Thunder Mountain, the Bull Demon King, his former sworn brother, comes out with an iron club, and they fight to a draw.','v0330.xyj_fan','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_fan.09','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'steals the Bull Demon King''s mount and takes his shape','string','While the Bull Demon King feasts with the dragon king of the Green Wave Pool, Sun Wukong steals his golden-eyed water-parting beast and takes his form.','v0330.xyj_fan','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_fan.10','hero.chinese.sun_wukong','NARRATIVE_ACTION','artifact.chinese.bajiao_shan',NULL,NULL,'Disguised as the Bull Demon King, Sun Wukong is welcomed home by Princess Iron Fan, who tells him the first fan was false and spits out the real plantain fan, small as an apricot leaf.','v0330.xyj_fan','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_fan.11','hero.chinese.sun_wukong','NARRATIVE_ACTION',NULL,'carries off the real fan but cannot shrink it','string','Sun Wukong learns from Princess Iron Fan the spell that makes the plantain fan grow to twelve feet, reveals himself and leaves with it on his shoulder, not knowing how to shrink it.','v0330.xyj_fan','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_fan.12','demon.chinese.niumowang','NARRATIVE_ACTION','artifact.chinese.bajiao_shan',NULL,NULL,'The Bull Demon King takes Zhu Bajie''s form, offers to carry the plantain fan for Sun Wukong and so tricks it back from him.','v0330.xyj_fan','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_fan.13','deity.chinese.nezha','NARRATIVE_ACTION','demon.chinese.niumowang',NULL,NULL,'When the Bull Demon King, fighting Sun Wukong through many transformations, becomes a giant white ox, the guardian vajra kings surround him and Nezha burns him with his fire wheel until he submits.','v0330.xyj_fan','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.xyj_fan.14','hero.chinese.sun_wukong','NARRATIVE_ACTION','place.chinese.flaming_mountains_xiyouji',NULL,NULL,'With the plantain fan surrendered by Princess Iron Fan, Sun Wukong fans the Flaming Mountains forty-nine times, putting out the fire for good, and the pilgrims cross; he returns the fan to her.','v0330.xyj_fan','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','LATER_RECEPTION','Journey to the West (Ming novel)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_bala.01','text.indian.ramayana','NARRATIVE_ACTION',NULL,'begins with the first śloka born of grief','string','In the opening of Book I Nārada tells Vālmīki of Rāma; Vālmīki''s pity for a curlew shot by a hunter becomes the first śloka, and Brahmā commands him to sing the whole story in that metre.','v0330.ram_bala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_bala.02','text.indian.ramayana','NARRATIVE_ACTION',NULL,'is first sung by Kuśa and Lava before Rāma','string','Book I tells how Vālmīki taught the poem to the twins Kuśa and Lava, who sang it before sages and then before Rāma himself in Ayodhyā.','v0330.ram_bala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_bala.03','hero.indian.dasharatha','NARRATIVE_CONDITION',NULL,'rules Ayodhyā but has no son','string','Book I describes Ayodhyā under King Daśaratha, who rules well but has no son and resolves on the horse sacrifice, recalling a prophecy about the sage Ṛṣyaśṛṅga.','v0330.ram_bala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_bala.04','hero.indian.dasharatha','NARRATIVE_ACTION',NULL,'brings the sage Ṛṣyaśṛṅga to Ayodhyā','string','Book I tells how the forest-bred sage Ṛṣyaśṛṅga, lured to drought-stricken Aṅga by courtesans, brought rain and married Śāntā, and how Daśaratha brought him to Ayodhyā to lead his sacrifice.','v0330.ram_bala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_bala.05','deity.hindu.vishnu','NARRATIVE_ACTION',NULL,'agrees to be born as Daśaratha''s four sons','string','During Daśaratha''s sacrifice the gods complain of Rāvaṇa, whom only a man can kill; Vishnu agrees to be born as Daśaratha''s four sons, and the gods beget vānaras such as Hanumān, Vālin and Sugrīva to help him.','v0330.ram_bala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_bala.06','hero.indian.dasharatha','NARRATIVE_ACTION','deity.hindu.rama',NULL,NULL,'A being rising from the sacrificial fire gives Daśaratha heavenly rice-milk for his queens, and Kausalyā bears Rāma, Kaikeyī Bharata, and Sumitrā the twins Lakṣmaṇa and Śatrughna.','v0330.ram_bala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_bala.07','hero.indian.vishvamitra','NARRATIVE_ACTION','deity.hindu.rama',NULL,NULL,'Viśvāmitra asks Daśaratha for the young Rāma to guard his sacrifice from Mārīca and Subāhu; the king refuses until Vasiṣṭha persuades him to keep his word.','v0330.ram_bala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_bala.08','deity.hindu.rama','NARRATIVE_ACTION',NULL,'slays the rākṣasī Tāṭakā','string','On the road with Viśvāmitra Rāma receives the spells Balā and Atibalā and, reluctant to kill a woman until the sage urges him, slays the rākṣasī Tāṭakā.','v0330.ram_bala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_bala.09','deity.hindu.rama','NARRATIVE_ACTION',NULL,'receives the divine weapons and protects the sacrifice','string','Viśvāmitra gives Rāma the divine weapons; at Siddhāśrama Rāma hurls Mārīca a hundred leagues into the sea, kills Subāhu and completes the sage''s sacrifice.','v0330.ram_bala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_bala.10','deity.hindu.ganga','NARRATIVE_ACTION',NULL,'descends from heaven through Śiva''s hair','string','Viśvāmitra tells Rāma how Bhagīratha''s austerities brought the Ganges down from heaven, how Śiva caught her proud fall in his hair, and how her waters raised Sagara''s sixty thousand sons to heaven.','v0330.ram_bala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_bala.11','hero.indian.vishvamitra','NARRATIVE_ACTION',NULL,'rises from king to brahmin sage through austerities','string','Śatānanda tells how Viśvāmitra, a king humbled by Vasiṣṭha over the wish-cow Śabalā, rose through thousands of years of austerities, despite Menakā and his own anger, to be acknowledged a brahmin sage.','v0330.ram_bala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_bala.12','hero.indian.ahalya','NARRATIVE_ACTION',NULL,'is released from Gautama''s curse when Rāma enters the hermitage','string','Book I tells how Ahalyā, cursed by her husband Gautama after Indra deceived her in Gautama''s form, lived unseen in the deserted hermitage until Rāma''s arrival released her.','v0330.ram_bala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_bala.13','deity.hindu.rama','NARRATIVE_ACTION','deity.hindu.sita',NULL,NULL,'At Mithilā Rāma lifts, strings and breaks the bow of Śiva that no king could lift, and Janaka, who found Sītā in a ploughed furrow, gives her to him.','v0330.ram_bala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_bala.14','hero.indian.parashurama','NARRATIVE_ACTION','deity.hindu.rama',NULL,NULL,'After the four princes'' weddings at Mithilā, Paraśurāma challenges Rāma with the bow of Vishnu; Rāma strings it, and Paraśurāma, recognising Vishnu, gives up his worlds won by penance.','v0330.ram_bala','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_ayodhya.01','hero.indian.dasharatha','NARRATIVE_ACTION',NULL,'resolves to consecrate Rāma as heir','string','Aging and seeing ill omens, Daśaratha proposes Rāma as heir to an assembly that acclaims him, and orders the consecration for the next day while Bharata is away.','v0330.ram_ayodhya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_ayodhya.02','hero.indian.kaikeyi','NARRATIVE_ACTION',NULL,'is persuaded to claim her two old boons','string','Mantharā persuades Kaikeyī that Rāma''s consecration will ruin her and Bharata, and reminds her of the two boons Daśaratha promised when she saved him in the war against Śambara.','v0330.ram_ayodhya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_ayodhya.03','hero.indian.kaikeyi','NARRATIVE_ACTION',NULL,'claims Bharata''s consecration and Rāma''s exile','string','Lying in the chamber of wrath, Kaikeyī makes Daśaratha swear by Rāma and claims her two boons: Bharata''s consecration and Rāma''s exile to the Daṇḍaka forest for fourteen years.','v0330.ram_ayodhya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_ayodhya.04','hero.indian.dasharatha','NARRATIVE_ACTION',NULL,'begs Kaikeyī all night in vain','string','Through the night Daśaratha begs Kaikeyī to withdraw her demand, but she invokes his duty to keep his word, and at dawn sends Sumantra to summon Rāma.','v0330.ram_ayodhya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_ayodhya.05','deity.hindu.rama','NARRATIVE_ACTION',NULL,'accepts exile without a change of face','string','Told by Kaikeyī of the two boons, Rāma accepts exile without a change of face, saying he would give up kingdom and life for his father''s word, and leaves to take leave of his mother.','v0330.ram_ayodhya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_ayodhya.06','hero.indian.lakshmana','NARRATIVE_ACTION',NULL,'offers to seize the throne for Rāma and is calmed','string','When Kausalyā collapses at the news and Lakṣmaṇa offers to seize the throne by force, Rāma calms his brother, attributing Kaikeyī''s demand to fate, and receives his mother''s blessing.','v0330.ram_ayodhya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_ayodhya.07','deity.hindu.sita','NARRATIVE_ACTION',NULL,'insists on sharing Rāma''s exile','string','Told to stay in Ayodhyā, Sītā answers that a wife shares her husband''s lot, that the forest with Rāma is better than heaven, and threatens to die if left behind, until Rāma agrees to take her.','v0330.ram_ayodhya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_ayodhya.08','hero.indian.lakshmana','NARRATIVE_ACTION',NULL,'follows Rāma into exile in bark garments','string','Lakṣmaṇa insists on following Rāma; the three give away their wealth and put on the bark garments Kaikeyī brings, while Vasiṣṭha protests that Sītā was never sentenced to wear them.','v0330.ram_ayodhya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_ayodhya.09','deity.hindu.rama','NARRATIVE_ACTION',NULL,'leaves Ayodhyā and crosses the Ganges','string','Rāma leaves Ayodhyā with the city weeping behind him, slips away from the citizens at the Tamasā, is welcomed by the Niṣāda chief Guha, mats his hair and crosses the Ganges while Sītā prays to Gaṅgā.','v0330.ram_ayodhya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_ayodhya.10','deity.hindu.rama','NARRATIVE_ACTION',NULL,'settles on Mount Citrakūṭa','string','On the sage Bharadvāja''s advice Rāma, Sītā and Lakṣmaṇa cross the Yamunā and settle in a leaf hut on Mount Citrakūṭa by the Mandākinī.','v0330.ram_ayodhya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_ayodhya.11','hero.indian.dasharatha','NARRATIVE_ACTION',NULL,'dies of grief, fulfilling an old curse','string','On the sixth night after Rāma''s departure Daśaratha tells Kausalyā how in youth he killed a young ascetic by mistake and was cursed by the blind father to die grieving for a son, and dies calling Rāma''s name.','v0330.ram_ayodhya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_ayodhya.12','hero.indian.bharata','NARRATIVE_ACTION',NULL,'rebukes Kaikeyī and refuses the throne','string','Returning to find his father dead and Rāma exiled for his sake, Bharata rebukes Kaikeyī, stops Śatrughna from killing Mantharā, swears his innocence to Kausalyā and performs the funeral.','v0330.ram_ayodhya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_ayodhya.13','hero.indian.bharata','NARRATIVE_ACTION',NULL,'leads the army to bring Rāma back','string','Bharata leads the court and army toward the forest to bring Rāma back; Guha and Bharadvāja first suspect him and then honour him, Bharadvāja conjuring a marvellous feast for the army.','v0330.ram_ayodhya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_ayodhya.14','hero.indian.bharata','NARRATIVE_ACTION','deity.hindu.rama',NULL,NULL,'When Bharata''s army approaches Citrakūṭa, Rāma rebukes Lakṣmaṇa''s suspicion; Bharata falls at Rāma''s feet and tells him their father has died, and Rāma offers ingudī pulp to Daśaratha''s spirit.','v0330.ram_ayodhya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_ayodhya.15','deity.hindu.rama','NARRATIVE_ACTION',NULL,'rejects Jābāli''s argument and keeps his father''s word','string','At Citrakūṭa Rāma refuses Bharata''s plea to return and sharply rejects the brahmin Jābāli''s materialist argument that a dead father''s promise does not bind, holding that truth is the root of dharma.','v0330.ram_ayodhya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_ayodhya.16','hero.indian.bharata','NARRATIVE_ACTION',NULL,'rules Ayodhyā in the name of Rāma''s sandals','string','Unable to move Rāma, Bharata takes his gold-adorned sandals, sets them on the throne and rules from Nandigrāma as an ascetic for fourteen years; Rāma moves south past the hermitage of Atri and Anasūyā into the Daṇḍaka forest.','v0330.ram_ayodhya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_aranya.01','deity.hindu.rama','NARRATIVE_ACTION',NULL,'vows to protect the hermits and buries Virādha','string','Entering the Daṇḍaka forest, Rāma promises the hermits protection from the rākṣasas, and with Lakṣmaṇa overcomes and buries the weapon-proof rākṣasa Virādha, who seized Sītā and turns out to be a cursed gandharva.','v0330.ram_aranya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_aranya.02','deity.hindu.sita','NARRATIVE_ACTION',NULL,'warns Rāma against violence without cause','string','Sītā warns Rāma against violence without cause, telling of a hermit corrupted by keeping a sword, and Rāma answers that a warrior must protect those who seek his help and keep his promise to the sages.','v0330.ram_aranya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_aranya.03','creature.hindu.jatayu','NARRATIVE_ACTION',NULL,'befriends Rāma and offers to guard Sītā','string','After ten years among the hermits and gifts of weapons from Agastya, Rāma meets the vulture-king Jaṭāyu, friend of Daśaratha, who offers to guard Sītā, and settles at Pañcavaṭī on the Godāvarī.','v0330.ram_aranya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_aranya.04','hero.indian.lakshmana','NARRATIVE_ACTION','demon.hindu.shurpanakha',NULL,NULL,'When Śūrpaṇakhā, rebuffed in jest by both brothers, rushes to devour Sītā, Lakṣmaṇa cuts off her nose and ears at Rāma''s command.','v0330.ram_aranya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_aranya.05','deity.hindu.rama','NARRATIVE_ACTION',NULL,'alone destroys Khara''s fourteen thousand','string','With Lakṣmaṇa guarding Sītā in a cave, Rāma alone destroys Khara''s army of fourteen thousand rākṣasas, Dūṣaṇa and Triśiras, and kills Khara with Agastya''s arrow.','v0330.ram_aranya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_aranya.06','demon.hindu.ravana','NARRATIVE_ACTION','deity.hindu.sita',NULL,NULL,'Told of Khara''s defeat and berated by Śūrpaṇakhā, who praises Sītā''s beauty before his court, Rāvaṇa resolves to abduct Sītā.','v0330.ram_aranya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_aranya.07','demon.hindu.maricha','NARRATIVE_ACTION',NULL,'warns Rāvaṇa and is forced to obey','string','Mārīca, who has lived in terror of Rāma since his boyhood arrow, warns Rāvaṇa against abducting Sītā, but agrees to become the golden deer when Rāvaṇa threatens to kill him.','v0330.ram_aranya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_aranya.08','demon.hindu.maricha','NARRATIVE_ACTION',NULL,'becomes a jewelled golden deer','string','Mārīca takes the form of a jewelled golden deer; Sītā begs Rāma to catch it despite Lakṣmaṇa''s warning, and Rāma leaves Lakṣmaṇa to guard her while he pursues it.','v0330.ram_aranya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_aranya.09','deity.hindu.sita','NARRATIVE_ACTION','hero.indian.lakshmana',NULL,NULL,'When the dying Mārīca cries out in Rāma''s voice, Sītā accuses Lakṣmaṇa of wanting Rāma dead in order to possess her, until he leaves to search for Rāma, calling the forest gods to witness.','v0330.ram_aranya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_aranya.10','demon.hindu.ravana','NARRATIVE_ACTION',NULL,'woos Sītā in the guise of an ascetic','string','Disguised as a wandering brahmin, Rāvaṇa is welcomed by Sītā as a guest, then reveals himself and asks her to be his queen in Laṅkā; she scorns him as a jackal coveting a lioness.','v0330.ram_aranya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_aranya.11','creature.hindu.jatayu','NARRATIVE_ACTION','demon.hindu.ravana',NULL,NULL,'The aged vulture-king Jaṭāyu fights Rāvaṇa in the sky to save Sītā, wrecking his chariot and breaking his bow, until Rāvaṇa cuts off his wings and feet.','v0330.ram_aranya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_aranya.12','demon.hindu.ravana','NARRATIVE_ACTION','place.hindu.lanka',NULL,NULL,'In Laṅkā Rāvaṇa shows Sītā his palace and offers to be her slave; when she refuses, speaking across a blade of grass, he gives her twelve months and confines her in the aśoka grove.','v0330.ram_aranya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_aranya.13','deity.hindu.rama','NARRATIVE_ACTION','creature.hindu.jatayu',NULL,NULL,'Finding the hut empty, Rāma is restrained by Lakṣmaṇa from destroying the worlds in grief, learns from the dying Jaṭāyu that Rāvaṇa took Sītā south and cremates him as a father.','v0330.ram_aranya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_aranya.14','deity.hindu.rama','NARRATIVE_ACTION',NULL,'is directed by Kabandha toward Sugrīva','string','Rāma and Lakṣmaṇa cut off the arms of the headless Kabandha, whose cremation releases a celestial who directs them to Sugrīva; the aged ascetic Śabarī welcomes Rāma and rises to heaven.','v0330.ram_aranya','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_kishkindha.01','deity.hindu.rama','NARRATIVE_ACTION',NULL,'grieves for Sītā in spring at Lake Pampā','string','In spring at Lake Pampā the beauty of the season deepens Rāma''s grief for Sītā until Lakṣmaṇa urges him to take heart.','v0330.ram_kishkindha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_kishkindha.02','deity.hindu.hanuman','NARRATIVE_ACTION',NULL,'greets Rāma disguised as an ascetic','string','Sent by Sugrīva and disguised as an ascetic, Hanumān questions Rāma and Lakṣmaṇa with such eloquence that Rāma praises his speech, and carries the brothers to Sugrīva.','v0330.ram_kishkindha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_kishkindha.03','hero.indian.sugriva','NARRATIVE_ACTION','deity.hindu.rama',NULL,NULL,'Rāma and Sugrīva swear friendship around a sacred fire kindled by Hanumān; Sugrīva shows the ornaments Sītā dropped, which Rāma recognises, and Lakṣmaṇa knows only her anklets.','v0330.ram_kishkindha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_kishkindha.04','hero.indian.valin','NARRATIVE_ACTION','hero.indian.sugriva',NULL,NULL,'Sugrīva tells how, after he sealed the cave where Vālin pursued the asura Māyāvī and took the throne believing him dead, Vālin returned, drove him out and took his wife Rumā.','v0330.ram_kishkindha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_kishkindha.05','deity.hindu.rama','NARRATIVE_ACTION',NULL,'shoots one arrow through seven sāl trees','string','To convince Sugrīva of his strength, Rāma kicks Dundubhi''s skeleton ten leagues with his toe and shoots an arrow through seven sāl trees, a mountain and the earth.','v0330.ram_kishkindha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_kishkindha.06','deity.hindu.rama','NARRATIVE_ACTION','hero.indian.valin',NULL,NULL,'At the second duel, with Sugrīva marked by a garland, Rāma shoots Vālin in the chest from behind a tree after Vālin ignores Tārā''s warning about Sugrīva''s new ally.','v0330.ram_kishkindha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_kishkindha.07','hero.indian.valin','NARRATIVE_ACTION','deity.hindu.rama',NULL,NULL,'The dying Vālin reproaches Rāma for shooting him from hiding; Rāma answers that Vālin deserved death for taking his brother''s wife and that he was bound by his promise; Vālin accepts, entrusts Aṅgada to Sugrīva, and Tārā laments.','v0330.ram_kishkindha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_kishkindha.08','hero.indian.sugriva','NARRATIVE_ACTION',NULL,'forgets his promise during the rains','string','Crowned king of Kiṣkindhā, Sugrīva spends the rains and the start of autumn in pleasure and forgets his promise, while Rāma waits on Mount Prasravaṇa longing for Sītā.','v0330.ram_kishkindha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_kishkindha.09','hero.indian.lakshmana','NARRATIVE_ACTION','hero.indian.sugriva',NULL,NULL,'Sent by Rāma when Sugrīva forgets his promise, Lakṣmaṇa storms into Kiṣkindhā and shakes the palace with his bowstring; calmed by Tārā, he brings the repentant Sugrīva to Rāma as the monkey armies gather.','v0330.ram_kishkindha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_kishkindha.10','deity.hindu.hanuman','NARRATIVE_ACTION',NULL,'receives Rāma''s ring for Sītā','string','Sugrīva sends search parties to the four quarters with a month''s deadline; Rāma gives Hanumān, who goes south with Aṅgada and Jāmbavān, his ring engraved with his name as a token for Sītā.','v0330.ram_kishkindha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_kishkindha.11','deity.hindu.hanuman','NARRATIVE_ACTION',NULL,'despairs with the southern search party','string','The southern search party loses its month in the enchanted cave of the ascetic Svayamprabhā, who sends them to the southern ocean, where Aṅgada and the monkeys resolve to fast to death.','v0330.ram_kishkindha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_kishkindha.12','deity.hindu.hanuman','NARRATIVE_ACTION',NULL,'is roused by Jāmbavān to leap the sea','string','Jaṭāyu''s brother Sampāti, whose wings regrow as he speaks, sees Sītā in Laṅkā a hundred leagues across the sea, and the bear-king Jāmbavān recounts Hanumān''s birth and powers until he swells to the size of a mountain.','v0330.ram_kishkindha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_sundara.01','deity.hindu.hanuman','NARRATIVE_ACTION',NULL,'leaps from Mount Mahendra and declines to rest','string','Hanumān leaps from Mount Mahendra, shaking the mountain, and declines to rest on the golden mountain Maināka, which the Ocean raises for him in gratitude to the Ikṣvākus.','v0330.ram_sundara','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_sundara.02','deity.hindu.hanuman','NARRATIVE_ACTION',NULL,'passes Surasā''s test and kills Siṃhikā','string','Hanumān passes the test of Surasā by shrinking to a thumb''s size and darting in and out of her widening mouth, and kills the shadow-seizing demoness Siṃhikā from within.','v0330.ram_sundara','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_sundara.03','deity.hindu.hanuman','NARRATIVE_ACTION','place.hindu.lanka',NULL,NULL,'Shrunk to a cat''s size, Hanumān enters Laṅkā by night and knocks down the city''s guardian goddess, who recognises the sign Brahmā foretold of the rākṣasas'' doom.','v0330.ram_sundara','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_sundara.04','deity.hindu.hanuman','NARRATIVE_ACTION',NULL,'searches Rāvaṇa''s palace and mistakes Mandodarī for Sītā','string','Searching Rāvaṇa''s palace by night, Hanumān mistakes the sleeping queen Mandodarī for Sītā, then reasons that Sītā would never sleep adorned and at ease beside another man.','v0330.ram_sundara','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_sundara.05','deity.hindu.hanuman','NARRATIVE_ACTION','deity.hindu.sita',NULL,NULL,'From a śiṃśapā tree in the aśoka grove Hanumān recognises Sītā, thin and unadorned among hideous rākṣasī guards, by Rāma''s description and by ornaments matching those she had dropped.','v0330.ram_sundara','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_sundara.06','deity.hindu.sita','NARRATIVE_ACTION','demon.hindu.ravana',NULL,NULL,'When Rāvaṇa woos and threatens her in the aśoka grove, Sītā answers him across a blade of grass that she belongs to Rāma as light to the sun, and he leaves her two months before he will have her killed.','v0330.ram_sundara','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_sundara.07','deity.hindu.sita','NARRATIVE_ACTION',NULL,'is protected by Trijaṭā''s dream of Rāma''s victory','string','When the rākṣasīs threaten to devour Sītā, the old rākṣasī Trijaṭā tells them of her dream of Rāma''s triumph and Rāvaṇa''s ruin, and they stop threatening her.','v0330.ram_sundara','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_sundara.08','deity.hindu.hanuman','NARRATIVE_ACTION',NULL,'sings Rāma''s story to Sītā from the tree','string','Seeing Sītā about to hang herself with her braid, Hanumān softly sings Rāma''s story from the tree in ordinary speech so as not to frighten her.','v0330.ram_sundara','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_sundara.09','deity.hindu.hanuman','NARRATIVE_ACTION','deity.hindu.sita',NULL,NULL,'Hanumān gives Sītā Rāma''s ring; she refuses to be carried away on his back because she will not willingly touch another man and Rāma himself must rescue her, and gives him her crest-jewel as a token.','v0330.ram_sundara','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_sundara.10','deity.hindu.sita','NARRATIVE_ACTION',NULL,'tells the secret story of the crow as a token','string','As a token known only to her and Rāma, Sītā tells Hanumān how Rāma once loosed Brahmā''s weapon in a blade of grass against a crow, a son of Indra, that pecked her breast on Citrakūṭa.','v0330.ram_sundara','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_sundara.11','deity.hindu.hanuman','NARRATIVE_ACTION','demon.hindu.indrajit',NULL,NULL,'Hanumān wrecks the aśoka grove, kills Rāvaṇa''s guards, generals and son Akṣa, and lets himself be taken before Rāvaṇa after Indrajit binds him with the weapon of Brahmā.','v0330.ram_sundara','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_sundara.12','deity.hindu.hanuman','NARRATIVE_ACTION','demon.hindu.ravana',NULL,NULL,'Before Rāvaṇa, Hanumān declares himself Sugrīva''s envoy and urges him to return Sītā since his boon does not protect him from men and monkeys; Vibhīṣaṇa saves him from execution because envoys may not be killed.','v0330.ram_sundara','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_sundara.13','deity.hindu.hanuman','NARRATIVE_ACTION','place.hindu.lanka',NULL,NULL,'With his tail set alight by Rāvaṇa''s order but made cool by Sītā''s prayer to the fire god, Hanumān breaks free and burns Laṅkā, sparing Vibhīṣaṇa''s house, and returns to find Sītā unharmed.','v0330.ram_sundara','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_sundara.14','deity.hindu.hanuman','NARRATIVE_ACTION','deity.hindu.rama',NULL,NULL,'Hanumān leaps back across the sea, the monkeys celebrate in Sugrīva''s honey grove, and he gives Rāma Sītā''s crest-jewel, whereupon Rāma embraces him as the only reward equal to his deed.','v0330.ram_sundara','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_yuddha.01','hero.indian.sugriva','NARRATIVE_ACTION','deity.hindu.rama',NULL,NULL,'After Hanumān''s report on Laṅkā''s defences, Rāma and Sugrīva march the army of monkeys and bears to the southern sea, Rāma riding on Hanumān''s shoulders.','v0330.ram_yuddha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_yuddha.02','hero.indian.vibhishana','NARRATIVE_ACTION','demon.hindu.ravana',NULL,NULL,'At Rāvaṇa''s council Vibhīṣaṇa, citing ill omens, urges the return of Sītā and peace with Rāma, and is denounced by Rāvaṇa as a traitor to his house.','v0330.ram_yuddha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_yuddha.03','deity.hindu.rama','NARRATIVE_ACTION','hero.indian.vibhishana',NULL,NULL,'Over Sugrīva''s objection that he is a spy, Rāma receives Vibhīṣaṇa on the principle that he protects anyone who seeks his refuge, even Rāvaṇa himself, and consecrates him king of Laṅkā with sea water.','v0330.ram_yuddha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_yuddha.04','deity.hindu.rama','NARRATIVE_ACTION',NULL,'crosses to Laṅkā by the bridge built by Nala','string','When the Ocean ignores his three-day fast, Rāma threatens it with his arrows until the Ocean rises and tells him that Nala, son of Viśvakarman, can build a bridge; the monkeys build it in five days and cross to Laṅkā.','v0330.ram_yuddha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_yuddha.05','demon.hindu.ravana','NARRATIVE_ACTION','deity.hindu.sita',NULL,NULL,'Rāvaṇa tries to break Sītā with an illusory severed head of Rāma, and rejects the ultimatum brought by Aṅgada, who escapes after killing the rākṣasas sent to seize him.','v0330.ram_yuddha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_yuddha.06','demon.hindu.indrajit','NARRATIVE_ACTION','deity.hindu.rama',NULL,NULL,'Fighting invisibly from the clouds, Indrajit binds Rāma and Lakṣmaṇa with serpent arrows until Garuḍa descends, the serpents flee and the brothers are healed.','v0330.ram_yuddha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_yuddha.07','demon.hindu.kumbhakarna','NARRATIVE_ACTION',NULL,'is woken to fight for his brother','string','After Rāvaṇa is beaten and spared by Rāma, the giant Kumbhakarṇa, cursed to sleep for months, is woken with drums and a thousand elephants, rebukes his brother for taking Sītā, and goes out to fight for him.','v0330.ram_yuddha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_yuddha.08','deity.hindu.rama','NARRATIVE_ACTION','demon.hindu.kumbhakarna',NULL,NULL,'After Kumbhakarṇa devours monkeys and carries off Sugrīva, Rāma shoots off his arms and legs, fills his mouth with arrows and cuts off his head with the arrow of Indra.','v0330.ram_yuddha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_yuddha.09','deity.hindu.hanuman','NARRATIVE_ACTION',NULL,'brings the whole mountain of healing herbs','string','When Indrajit''s weapon of Brahmā fells the whole army, Hanumān, sent by Jāmbavān, tears up the Himalayan mountain of healing herbs and carries it to Laṅkā, reviving Rāma, Lakṣmaṇa and the fallen army.','v0330.ram_yuddha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_yuddha.10','hero.indian.lakshmana','NARRATIVE_ACTION','demon.hindu.indrajit',NULL,NULL,'After Indrajit kills an illusory Sītā to break the besiegers'' spirit, Lakṣmaṇa, guided by Vibhīṣaṇa, attacks him at the Nikumbhilā shrine before his sacrifice is complete and slays him with the arrow of Indra.','v0330.ram_yuddha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_yuddha.11','deity.hindu.hanuman','NARRATIVE_ACTION','hero.indian.lakshmana',NULL,NULL,'When Rāvaṇa strikes Lakṣmaṇa down with a dart given him by Maya, Hanumān carries Lakṣmaṇa back and, sent by the physician Suṣeṇa, again brings a mountain peak of herbs that heals him.','v0330.ram_yuddha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_yuddha.12','deity.hindu.rama','NARRATIVE_ACTION','demon.hindu.ravana',NULL,NULL,'In Indra''s chariot driven by Mātali, Rāma strikes off Rāvaṇa''s regrowing heads a hundred times and finally kills him with Agastya''s arrow charged with the weapon of Brahmā.','v0330.ram_yuddha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_yuddha.13','hero.indian.vibhishana','NARRATIVE_ACTION',NULL,'is consecrated king of Laṅkā','string','After Mandodarī''s lament, Rāma tells Vibhīṣaṇa that enmity ends with death and bids him give Rāvaṇa a royal funeral; Vibhīṣaṇa is consecrated king of Laṅkā, and Sītā refuses to let Hanumān punish her rākṣasī guards.','v0330.ram_yuddha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_yuddha.14','deity.hindu.sita','NARRATIVE_ACTION',NULL,'enters the fire to prove her faithfulness','string','When Rāma rejects her in public for having lived in Rāvaṇa''s house, Sītā answers that her heart was always his and her capture was not her fault, has Lakṣmaṇa build a pyre and enters the fire, praying to Agni.','v0330.ram_yuddha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_yuddha.15','deity.hindu.agni','NARRATIVE_ACTION','deity.hindu.sita',NULL,NULL,'Agni rises from the fire holding Sītā unharmed and declares her pure; Brahmā reveals Rāma as Nārāyaṇa and Sītā as Lakṣmī, Daśaratha appears from heaven, and Indra restores the fallen monkeys and bears.','v0330.ram_yuddha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_yuddha.16','hero.indian.vibhishana','NARRATIVE_ACTION',NULL,'gives Rāma the flying chariot Puṣpaka','string','Vibhīṣaṇa gives Rāma the flying chariot Puṣpaka; Rāma flies home with Sītā and his allies, showing her the places of their story, and sends Hanumān ahead to tell Bharata.','v0330.ram_yuddha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ram_yuddha.17','deity.hindu.rama','NARRATIVE_ACTION',NULL,'is crowned king of Ayodhyā','string','Bharata returns Rāma''s sandals and kingdom, Rāma is consecrated king of Ayodhyā with Sītā beside him, Sītā gives her pearl necklace to Hanumān, and the epic describes the peace of Rāma''s reign.','v0330.ram_yuddha','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Vālmīki Rāmāyaṇa (Griffith translation, vulgate text)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_wanderings.01','deity.greek.athena','NARRATIVE_ACTION',NULL,'persuades Zeus to let Odysseus return home','string','In the Odyssey''s opening council, while Poseidon is away, Athena persuades Zeus to let Odysseus, held by Calypso, return home, and proposes to send Hermes to Calypso and to rouse Telemachus herself.','v0330.ody_wanderings','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_wanderings.02','hero.greek.telemachus','NARRATIVE_ACTION',NULL,'is roused by Athena disguised as Mentes','string','Athena, disguised as Mentes, tells Telemachus that Odysseus lives and urges him to confront the suitors and seek news of his father at Pylos and Sparta; Telemachus asserts himself as master of the house.','v0330.ody_wanderings','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_wanderings.03','hero.greek.penelope','NARRATIVE_ACTION',NULL,'weaves Laertes'' shroud by day and unpicks it by night','string','At the Ithacan assembly Antinous reveals how Penelope put off the suitors for three years by weaving a shroud for Laertes by day and unpicking it by night; Telemachus refuses to send her away and secretly sails with Athena''s help.','v0330.ody_wanderings','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_wanderings.04','hero.greek.telemachus','NARRATIVE_ACTION',NULL,'learns at Sparta that Odysseus is held by Calypso','string','Telemachus hears from Nestor at Pylos of the Greeks'' homecomings and from Menelaus at Sparta that Proteus told him Odysseus lives, held by Calypso, while the suitors lay an ambush for his return.','v0330.ody_wanderings','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_wanderings.05','deity.greek.calypso','NARRATIVE_ACTION','hero.greek.odysseus',NULL,NULL,'Ordered by Zeus through Hermes, Calypso releases Odysseus after seven years, and Odysseus tells her that though Penelope cannot match a goddess''s beauty, he longs every day for home.','v0330.ody_wanderings','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_wanderings.06','deity.greek.poseidon','NARRATIVE_ACTION','hero.greek.odysseus',NULL,NULL,'Seeing Odysseus on his raft within sight of the Phaeacians'' land, Poseidon wrecks it with a storm; aided by Ino''s veil and a river god, Odysseus swims ashore after two days and nights.','v0330.ody_wanderings','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_wanderings.07','hero.greek.odysseus','NARRATIVE_ACTION',NULL,'supplicates the princess Nausicaa','string','Shipwrecked on the Phaeacians'' shore, Odysseus is woken by Nausicaa and her maids at play; he supplicates her with courteous words, and she gives him clothes and directs him to her mother at the palace.','v0330.ody_wanderings','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_wanderings.08','hero.greek.odysseus','NARRATIVE_ACTION',NULL,'reveals his name at the Phaeacian court','string','At the Phaeacian court Odysseus wins the discus throw, weeps when the bard Demodocus sings of the wooden horse, and at King Alcinous''s question reveals his name and begins to tell his wanderings.','v0330.ody_wanderings','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_wanderings.09','hero.greek.odysseus','NARRATIVE_ACTION',NULL,'drags his men away from the Lotus-eaters','string','Odysseus tells how after a costly raid on the Cicones his scouts ate the lotus in the land of the Lotus-eaters and forgot their homecoming, and how he dragged them weeping back to the ships.','v0330.ody_wanderings','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_wanderings.10','creature.greek.polyphemus','NARRATIVE_ACTION','hero.greek.odysseus',NULL,NULL,'The Cyclops Polyphemus seals Odysseus and his men in his cave with a stone, scorns Zeus as protector of guests and eats two of the men at night and two more in the morning.','v0330.ody_wanderings','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_wanderings.11','hero.greek.odysseus','NARRATIVE_ACTION','creature.greek.polyphemus',NULL,NULL,'Telling Polyphemus his name is ''Nobody'', Odysseus makes him drunk and blinds his single eye with a heated stake, so that the other Cyclopes leave when he cries that ''Nobody'' is killing him.','v0330.ody_wanderings','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_wanderings.12','creature.greek.polyphemus','NARRATIVE_ACTION','hero.greek.odysseus',NULL,NULL,'Odysseus and his men escape the blind Polyphemus clinging under his rams; when Odysseus boastfully shouts his true name, the Cyclops prays to Poseidon that Odysseus reach home late, alone and to find trouble there.','v0330.ody_wanderings','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_wanderings.13','hero.greek.odysseus','NARRATIVE_ACTION',NULL,'loses his fleet after the bag of winds is opened','string','Odysseus tells how his men opened Aeolus''s bag of winds within sight of Ithaca and were blown back, and how the man-eating Laestrygonians destroyed every ship but his own.','v0330.ody_wanderings','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_wanderings.14','deity.greek.circe','NARRATIVE_ACTION','hero.greek.odysseus',NULL,NULL,'Circe turns Odysseus''s men into swine; protected by the herb moly from Hermes, Odysseus makes her swear not to harm him and restore them, stays a year, and is told he must consult Tiresias in the house of Hades.','v0330.ody_wanderings','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_wanderings.15','hero.greek.odysseus','NARRATIVE_ACTION',NULL,'consults Tiresias among the dead','string','At the edge of the world Odysseus calls up the dead with blood; Tiresias prophesies his late and lonely return and his revenge on the suitors, his mother''s shade slips from his embrace, and Achilles says he would rather be a hired hand on earth than king among the dead.','v0330.ody_wanderings','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_wanderings.16','hero.greek.odysseus','NARRATIVE_ACTION','creature.greek.sirens',NULL,NULL,'Following Circe''s advice, Odysseus seals his crew''s ears with wax and has himself bound to the mast, so that he hears the Sirens'' song of all knowledge without being able to turn to them.','v0330.ody_wanderings','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_wanderings.17','creature.greek.scylla','NARRATIVE_ACTION','hero.greek.odysseus',NULL,NULL,'Passing between Scylla and Charybdis as Circe advised, Odysseus loses six of his strongest men to the six heads of Scylla while the crew watches Charybdis swallow the sea.','v0330.ody_wanderings','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_wanderings.18','deity.greek.helios','NARRATIVE_ACTION',NULL,'has Zeus destroy Odysseus''s ship for the slaughter of his cattle','string','When Odysseus''s starving men slaughter the cattle of the Sun on Thrinacia, Helios demands vengeance and Zeus''s thunderbolt destroys the ship; Odysseus alone survives, escapes Charybdis and drifts to Calypso''s island.','v0330.ody_wanderings','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_homecoming.01','deity.greek.athena','NARRATIVE_ACTION',NULL,'disguises Odysseus as an old beggar on his return to Ithaca','string','When the Phaeacians leave the sleeping Odysseus in Ithaca, Athena reveals herself, praises his cunning, helps him hide his treasure and disguises him as an old beggar.','v0330.ody_homecoming','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_homecoming.02','person.greek.eumaeus','NARRATIVE_ACTION','hero.greek.odysseus',NULL,NULL,'The swineherd Eumaeus shelters the disguised Odysseus, refuses to believe his oath that Odysseus will return, gives him his own cloak and tells how he was kidnapped as a king''s son and sold to Laertes.','v0330.ody_homecoming','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_homecoming.03','hero.greek.telemachus','NARRATIVE_ACTION',NULL,'evades the suitors'' ambush on his return from Sparta','string','Warned by Athena of the suitors'' ambush in the strait, Telemachus leaves Sparta, takes the fugitive seer Theoclymenus aboard at Pylos, avoids the ambush by sailing at night and lands secretly on Ithaca.','v0330.ody_homecoming','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_homecoming.04','hero.greek.odysseus','NARRATIVE_ACTION','hero.greek.telemachus',NULL,NULL,'In the swineherd''s hut Athena restores Odysseus''s form and he reveals himself to Telemachus; father and son weep together and plan the suitors'' death in secrecy.','v0330.ody_homecoming','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_homecoming.05','hero.greek.odysseus','NARRATIVE_ACTION',NULL,'is recognised by his old dog Argos at the palace door','string','Entering Ithaca as a beggar, Odysseus is kicked by Melanthius and restrains himself; at the palace door his old dog Argos recognises his voice, wags his tail and dies after twenty years.','v0330.ody_homecoming','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_homecoming.06','person.greek.antinous','NARRATIVE_ACTION','hero.greek.odysseus',NULL,NULL,'In his own hall the beggar Odysseus is struck with a footstool by Antinous, breaks the jaw of the beggar Irus in a boxing match staged by the suitors, and vainly warns the kindly Amphinomus to leave.','v0330.ody_homecoming','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_homecoming.07','person.greek.eurycleia','NARRATIVE_ACTION','hero.greek.odysseus',NULL,NULL,'Washing the disguised Odysseus''s feet, his old nurse Eurycleia recognises the boar-tusk scar from his youth on Parnassus; he silences her while Athena keeps Penelope from noticing.','v0330.ody_homecoming','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_homecoming.08','hero.greek.penelope','NARRATIVE_ACTION',NULL,'announces the contest of the bow and the twelve axes','string','Penelope tells the disguised Odysseus her dream of an eagle killing twenty geese, distinguishes the gates of horn and ivory, and announces a contest of Odysseus''s bow and twelve axes; next day omens of the suitors'' doom multiply.','v0330.ody_homecoming','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_homecoming.09','weapon.greek.bow_of_odysseus','NARRATIVE_ACTION',NULL,'is strung by Odysseus, who shoots through the twelve axes','string','No suitor can string the bow Iphitus gave Odysseus; having revealed himself to Eumaeus and Philoetius, Odysseus strings it like a lyre and shoots through all twelve axes.','v0330.ody_homecoming','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_homecoming.10','hero.greek.odysseus','NARRATIVE_ACTION',NULL,'takes vengeance on the suitors from the threshold of his hall','string','From the threshold of his hall Odysseus kills Antinous with his first arrow, refuses Eurymachus''s offer of compensation and, with Telemachus, the two loyal herdsmen and Athena''s aegis, defeats the suitors, sparing the bard Phemius and the herald Medon.','v0330.ody_homecoming','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_homecoming.11','hero.greek.odysseus','NARRATIVE_ACTION',NULL,'forbids exulting over the dead and purifies his house','string','After the killing of the suitors Odysseus forbids Eurycleia to exult over the dead, punishes the twelve disloyal maids and Melanthius, and purifies the house with sulphur and fire.','v0330.ody_homecoming','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_homecoming.12','hero.greek.penelope','NARRATIVE_ACTION','hero.greek.odysseus',NULL,NULL,'Penelope tests the returned Odysseus by ordering his bed moved; his angry account of the bed built on a living olive trunk, a secret only they know, convinces her and they are reunited.','v0330.ody_homecoming','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_homecoming.13','hero.greek.laertes','NARRATIVE_ACTION','hero.greek.odysseus',NULL,NULL,'As Hermes leads the suitors'' souls to Hades, Odysseus finds his aged father Laertes working in his orchard; after testing him with a tale, he proves his identity by his scar and the trees Laertes once gave him.','v0330.ody_homecoming','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z'),
('claim.v0330.ody_homecoming.14','deity.greek.athena','NARRATIVE_ACTION',NULL,'ends the feud in Ithaca and establishes peace','string','When the suitors'' kin led by Eupeithes attack Odysseus at Laertes''s farm, Athena with Zeus''s sanction and thunderbolt stops the fighting and, in the guise of Mentor, establishes lasting peace in Ithaca.','v0330.ody_homecoming','SUPPORTED',0.9,'HIGH','VERIFIED','TEXT_SAYS','MYTHIC_NARRATIVE','Homeric Odyssey (Butler translation)',NULL,NULL,'2026-10-24T01:00:00Z');

