INSERT OR IGNORE INTO story_event_nodes(
    id,story_version_id,event_order,title_zh,title_en,summary_zh,summary_en,anchor_claim_id,event_entity_id,place_entity_id,location_kind,coordinate_policy,evidence_status,uncertainty_note,created_at
) VALUES
('storyevent.v0330.chinese_xiyouji_ch8_12.1','storyver.chinese.xiyouji_ch8_12',1,'灵山上的三藏真经','Three baskets of scripture on Spirit Mountain','如来把孙悟空压在五行山下以后，回到西天灵山雷音宝刹，不知不觉过了五百年。','Five hundred years after pinning Sun Wukong under the Mountain of Five Elements, the Buddha held the Ullambana feast on Spirit Mountain and described the four continents: the people of the southern continent of Jambudvīpa were greedy, lustful and quarrelsome, a sea of strife.','claim.v0330.xyj_origins.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch8_12.2','storyver.chinese.xiyouji_ch8_12',2,'五件宝贝与一路东行','Five treasures and the road east','如来非常高兴，说：别人去不得，须是观音尊者，神通广大，才可以去。','The delighted Buddha told Guanyin to travel half on cloud and half on mist, noting the distances for the pilgrim, and had Ānanda and Kāśyapa bring five treasures: a brocade cassock and a nine-ringed staff for the pilgrim — whoever wore the cassock would escape rebirth, whoever held the staff would escape poison — and three fillets with the spells Gold, Tight and Prohibition.','claim.v0330.xyj_origins.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch8_12.3','storyver.chinese.xiyouji_ch8_12',3,'流沙河与福陵山','The Flowing Sands River and Fuling Mountain','那妖魔叩头说：菩萨恕罪！','The demon said he had been the Curtain-Raising General who attended the imperial carriage; for breaking a crystal cup at the Peach Banquet he was flogged eight hundred times, banished and pierced by a flying sword every seven days, so hunger drove him to eat travellers.','claim.v0330.xyj_origins.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch8_12.4','storyver.chinese.xiyouji_ch8_12',4,'空中的玉龙与山下的猴王','The dragon in the air and the monkey under the mountain','菩萨和木叉继续东行，正走着，忽然看见半空中吊着一条玉龙，正在叫苦。','Further east Guanyin found a jade dragon hanging in the sky: the son of the Dragon King of the Western Sea, condemned for burning a pearl in his father''s hall.','claim.v0330.xyj_origins.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch8_12.5','storyver.chinese.xiyouji_ch8_12',5,'状元、绣球与金色鲤鱼','The top scholar, the embroidered ball and the golden carp','菩萨离开五行山，一路来到大唐国都长安。','Guanyin reached Chang''an and lodged in the earth-god''s shrine disguised as a scabby monk.','claim.v0330.xyj_origins.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','第九回陈光蕊故事见于清代以后的通行本，明代世德堂本没有这一回。','2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch8_12.6','storyver.chinese.xiyouji_ch8_12',6,'洪江渡口的劫难','Murder at the Hong River crossing','夫妻俩带着家僮来到洪江渡口，船夫刘洪、李彪撑船过来迎接。','At the Hong River crossing the boatmen Liu Hong and Li Biao ferried them, and Liu Hong coveted the young wife.','claim.v0330.xyj_origins.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','第九回陈光蕊故事见于清代以后的通行本，明代世德堂本没有这一回。','2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch8_12.7','storyver.chinese.xiyouji_ch8_12',7,'漂在江上的婴儿','A baby on the river','殷小姐在江州衙门里痛恨刘洪，恨不得食其肉、寝其皮，只因身怀有孕，未知男女，只得勉强忍耐。','In the Jiangzhou yamen Wenjiao bore a son.','claim.v0330.xyj_origins.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','第九回陈光蕊故事见于清代以后的通行本，明代世德堂本没有这一回。','2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch8_12.8','storyver.chinese.xiyouji_ch8_12',8,'江流儿寻母报仇','Jiangliu finds his mother','光阴似箭，江流长到十八岁，长老给他剃度出家，取法名玄奘，他一心参禅，持斋把素。','At eighteen Jiangliu was ordained as Xuanzang.','claim.v0330.xyj_origins.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','第九回陈光蕊故事见于清代以后的通行本，明代世德堂本没有这一回；有的版本还写到殷小姐最后从容自尽，本节不展开。','2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch8_12.9','storyver.chinese.xiyouji_ch8_12',9,'渔夫、樵夫与卖卦先生','A fisherman, a woodcutter and a fortune-teller','长安城外的泾河岸边，住着两个不登科的贤人：一个是渔翁，名叫张稍；一个是樵子，名叫李定。','Outside Chang''an, by the Jing River, the fisherman Zhang Shao and the woodcutter Li Ding, tipsy and trading verses, argued about whose trade was safer.','claim.v0330.xyj_origins.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch8_12.10','storyver.chinese.xiyouji_ch8_12',10,'龙王的赌局','The dragon king''s wager','龙王挤进卦铺，见袁守诚相貌稀奇、仪容秀丽，便请他占卜一课。','The dragon king asked about tomorrow''s weather.','claim.v0330.xyj_origins.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch8_12.11','storyver.chinese.xiyouji_ch8_12',11,'梦中斩龙','Beheaded in a dream','袁守诚坐在那里纹丝不动，龙王又抡起门板就打，骂道：你这妄言祸福的妖人，擅惑众心的泼汉！','Yuan Shoucheng laughed at the wrecked booth: he knew the scholar was the Jing River dragon king, who by changing heaven''s decree had earned execution at a quarter past noon tomorrow — and the executioner would be Chief Minister Wei Zheng.','claim.v0330.xyj_origins.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch8_12.12','storyver.chinese.xiyouji_ch8_12',12,'门神与太宗之死','The door gods and the emperor''s death','太宗见了龙头，心中又惊又悔，回宫后闷闷不乐。','From then on the dragon''s ghost came at night carrying its head, crying to Taizong to give back its life and come argue before the judges of the dead; once a heavenly lady waved a willow sprig and drove it off — Guanyin protecting him unseen.','claim.v0330.xyj_origins.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch8_12.13','storyver.chinese.xiyouji_ch8_12',13,'太宗游地府','The emperor in the underworld','太宗的魂魄出了五凤楼，恍恍惚惚，被引到一处荒郊，判官崔珏前来迎接，跪在路旁说：微臣有失远迎。','Taizong''s soul was received by the judge Cui Jue, who read Wei Zheng''s letter.','claim.v0330.xyj_origins.13',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch8_12.14','storyver.chinese.xiyouji_ch8_12',14,'刘全进瓜','Liu Quan delivers the melons','太宗还阳以后，大赦天下，把死囚都放回家中与父母妻子团聚，又出榜招贤，要找人把南瓜送到阴司去，答谢十代阎王——那是他在阴间答应过的。','Restored to life, Taizong freed the prisoners and sought someone to take melons to the Ten Kings as he had promised.','claim.v0330.xyj_origins.14',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch8_12.15','storyver.chinese.xiyouji_ch8_12',15,'袈裟与锡杖','The cassock and the staff','太宗要兑现在阴司许下的诺言，召集天下高僧，要选一位有德行的大阐都僧纲，在化生寺开设水陆大会。','To keep his underworld promise, Taizong summoned the eminent monks and the court recommended Xuanzang, a vegetarian from birth with a famous pedigree and mastery of the sutras; the emperor made him chief monk of the realm, with the altar at Huasheng Monastery.','claim.v0330.xyj_origins.15',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch8_12.16','storyver.chinese.xiyouji_ch8_12',16,'观音显圣','Guanyin reveals herself','水陆大会开到第七天，太宗亲自摆驾，带领文武百官到化生寺拈香。','On the seventh day of the mass, while Xuanzang preached from the high altar before the emperor, the scabby monk struck the altar and asked whether he could only teach the Lesser Vehicle.','claim.v0330.xyj_origins.16',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch8_12.17','storyver.chinese.xiyouji_ch8_12',17,'一捻故乡土','A pinch of home soil','话音刚落，玄奘从旁边闪出，走上前来，拜伏在地：贫僧不才，愿效犬马之劳，与陛下求取真经，祈保我王江山永固。','Xuanzang knelt and volunteered.','claim.v0330.xyj_origins.17',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch13_22.1','storyver.chinese.xiyouji_ch13_22',1,'双叉岭的虎穴','The tiger''s pit on Double Fork Ridge','三藏辞别了唐王，一路晓行夜宿，过了几天，来到大唐边境的河州卫。','Leaving the last Tang garrison at Hezhou before dawn, Sanzang and his two attendants fell into a pit on a thorny ridge.','claim.v0330.xyj_gather.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch13_22.2','storyver.chinese.xiyouji_ch13_22',2,'猎户刘伯钦','The hunter Liu Boqin','三藏独自一人牵着马往前走，走到半山中，忽见前面两只猛虎咆哮，后面几条长蛇盘绕，左边是毒虫，右边是怪兽。','Alone in the mountains, Sanzang was surrounded by tigers, serpents and strange beasts, until they scattered before a hunter in a leopard-skin cap with a steel trident: Liu Boqin, ''Guardian of the Mountain'', who fought and killed a tiger and took Sanzang home.','claim.v0330.xyj_gather.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch13_22.3','storyver.chinese.xiyouji_ch13_22',3,'两界山的猴王','The monkey of the Mountain of Two Frontiers','三藏正要和刘伯钦分别，忽然山脚下有人大叫：我师父来也！','As Sanzang was about to part from Liu Boqin, a voice cried from the foot of the mountain: ''My master has come!'' Boqin explained that a divine monkey had lain under this mountain — once called the Mountain of Five Elements — since Wang Mang''s time, fed on iron pellets and copper juice.','claim.v0330.xyj_gather.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch13_22.4','storyver.chinese.xiyouji_ch13_22',4,'六个强盗','Six robbers','刘伯钦见了，又惊又喜，辞别回去了。','Liu Boqin went home, and Sanzang gave his new disciple the nickname Pilgrim Sun.','claim.v0330.xyj_gather.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch13_22.5','storyver.chinese.xiyouji_ch13_22',5,'一顶嵌金花帽','A cap with a golden band','三藏孤孤零零，只得自己收拾行李，牵着马慢慢往西走。','Alone, Sanzang met an aged woman carrying a cotton robe and a cap with a golden band — her dead son''s, she said — and a spell called the Truth That Settles the Mind, also the Tight-Fillet Spell, to recite if his disciple disobeyed.','claim.v0330.xyj_gather.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch13_22.6','storyver.chinese.xiyouji_ch13_22',6,'鹰愁涧的白马','The white horse of Eagle Grief Gorge','师徒二人往西走了些日子，正是腊月寒天，来到蛇盘山鹰愁涧。','In the depth of winter, at Eagle Grief Gorge on Coiled Serpent Mountain, a dragon burst from the water and swallowed the white horse, saddle and all.','claim.v0330.xyj_gather.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch13_22.7','storyver.chinese.xiyouji_ch13_22',7,'观音禅院的大火','Fire at the Guanyin Chan Monastery','师徒行了两个月，来到一座观音禅院借宿。','After two months they lodged at a Guanyin Chan monastery whose 270-year-old abbot loved treasures.','claim.v0330.xyj_gather.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch13_22.8','storyver.chinese.xiyouji_ch13_22',8,'黑风山的熊精','The bear of Black Wind Mountain','悟空驾云来到黑风山，在山坡上听见三个妖魔正在说话：一个黑汉，一个道人，一个白衣秀士。','On Black Wind Mountain Wukong overheard three demons — a black fellow, a Taoist and a white-robed scholar — planning a ''Buddha-robe feast'' for the black one''s birthday.','claim.v0330.xyj_gather.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch13_22.9','storyver.chinese.xiyouji_ch13_22',9,'观音变作凌虚子','Guanyin as the Taoist Lingxuzi','两人走到半山，迎面来了一个道人，手里捧着一个玻璃盘，盘里放着两粒仙丹，正要去给熊精祝寿。','On the way they met a Taoist carrying two elixir pills as a birthday gift — the grey wolf spirit Lingxuzi, whom Wukong killed at once.','claim.v0330.xyj_gather.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch13_22.10','storyver.chinese.xiyouji_ch13_22',10,'高老庄的女婿','The son-in-law of Gao Village','师徒又走了几天，天色将晚，来到一座村庄。','At Gao Village in the land of Tibet, the squire Gao had married his third daughter Cuilan to a stranger named Zhu who had come three years earlier.','claim.v0330.xyj_gather.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch13_22.11','storyver.chinese.xiyouji_ch13_22',11,'云栈洞收八戒','Taking Bajie at the Cloud-Ladder Cave','悟空追到福陵山云栈洞，那妖怪拿着九齿钉钯出来迎战，两人从半夜一直斗到天明。','Wukong pursued the monster to the Cloud-Ladder Cave on Fuling Mountain and fought him from midnight to dawn.','claim.v0330.xyj_gather.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch13_22.12','storyver.chinese.xiyouji_ch13_22',12,'浮屠山的《心经》','The Heart Sutra on Pagoda Mountain','师徒三人离了高老庄，一路西行，走了一个月，来到浮屠山。','A month later, on Pagoda Mountain, they met the Crow''s Nest Chan master in a nest of twigs in a juniper.','claim.v0330.xyj_gather.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch13_22.13','storyver.chinese.xiyouji_ch13_22',13,'黄风岭的风魔','The wind demon of Yellow Wind Ridge','夏去秋来，师徒来到一座高山，名叫黄风岭。','In autumn they reached Yellow Wind Ridge.','claim.v0330.xyj_gather.13',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch13_22.14','storyver.chinese.xiyouji_ch13_22',14,'灵吉菩萨定风魔','Lingji Bodhisattva stills the wind demon','天色已晚，悟空和八戒在山间找人家借宿，只见一座庄院，一位老者出来迎接，听说悟空眼睛被风吹伤，就取出一种眼药，叫做“三花九子膏”，说能治一切风眼。','That night an old farmer gave Wukong an ointment, ''Three Flowers and Nine Seeds'', and next morning his eyes were brighter than ever — but the farmhouse had vanished: it had been conjured by the guardian spirits protecting the pilgrim.','claim.v0330.xyj_gather.14',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch13_22.15','storyver.chinese.xiyouji_ch13_22',15,'流沙河大战','Battle at the Flowing Sands River','师徒三人过了黄风岭，又走了些日子，来到一条大河前，只见浑波涌浪，水势滔滔，岸上立着一块石碑，写着三个篆字“流沙河”，下面还有四行小字：八百流沙界，三千弱水深。','Beyond Yellow Wind Ridge they reached a river with a stone tablet: ''Flowing Sands — eight hundred li of sands, three thousand fathoms of weak water; a goose feather will not float, a reed flower sinks to the bottom.'' A red-haired demon with nine skulls round his neck rushed out; Bajie fought him to a draw until Wukong, itching for a fight after a month without one, leapt in and drove him back under the water.','claim.v0330.xyj_gather.15',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch13_22.16','storyver.chinese.xiyouji_ch13_22',16,'九个骷髅做法船','A raft of nine skulls','菩萨叫来惠岸行者木叉，从袖中取出一个红葫芦，说：你可将此葫芦，同孙悟空到流沙河水面上，只叫“悟净”，他就出来了。','Guanyin sent Muzha with a red gourd: standing on the water he called ''Wujing!'', and the demon, hearing the name Guanyin had given him, surfaced at once.','claim.v0330.xyj_gather.16',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch27_31.1','storyver.chinese.xiyouji_ch27_31',1,'白虎岭上的妖精','A demon on White Tiger Ridge','师徒四众离了五庄观，往西又走了些日子，来到一座高山，山势险峻，峰岩重叠。','Days beyond the Wuzhuang Temple, on a steep mountain, Sanzang complained that he had eaten nothing all day and scolded Wukong for laziness.','claim.v0330.xyj_white_bone.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch27_31.2','storyver.chinese.xiyouji_ch27_31',2,'一打：送饭的村姑','The first blow: a village girl with food','那妖精摇身一变，变作一个月貌花容的女儿，说不尽那眉清目秀，齿白唇红，左手提着一个青砂罐，右手提着一个绿磁瓶，从西向东，直奔唐僧。','The demon became a lovely girl carrying a blue jar of fragrant rice and a green bottle of fried gluten, which she said she had vowed to offer to monks.','claim.v0330.xyj_white_bone.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch27_31.3','storyver.chinese.xiyouji_ch27_31',3,'二打：寻女的老妇','The second blow: an old woman seeking her daughter','悟空忍着头疼说：师父，你这般猜忌，就让我回去吧。','Spared after a promise to behave, Wukong shared the peaches.','claim.v0330.xyj_white_bone.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch27_31.4','storyver.chinese.xiyouji_ch27_31',4,'三打：念经的老翁','The third blow: an old man telling his beads','那妖精又脱了命，在半空里夸奖不尽道：好个猴王，着然有眼！','Admiring Wukong''s eyes, the demon tried once more before the pilgrims passed beyond her territory: she became a white-haired old man with a dragon-headed staff, telling his beads and chanting.','claim.v0330.xyj_white_bone.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch27_31.5','storyver.chinese.xiyouji_ch27_31',5,'一纸贬书','A letter of dismissal','唐僧见了那堆骷髅，说：悟空，这个人才死了，怎么就化作一堆骷髅？','Sanzang half believed the inscription, but Bajie whispered that Wukong had conjured it to escape the spell, and Sanzang recited again.','claim.v0330.xyj_white_bone.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch27_31.6','storyver.chinese.xiyouji_ch27_31',6,'水帘洞重整旗鼓','Rebuilding the Water Curtain Cave','悟空独自一个，含着眼泪，在空中驾着筋斗云，忽听得东洋大海潮声响亮，不禁想起唐僧，止不住腮边泪坠，停云住步，良久方去。','Flying home in tears, Wukong heard the roar of the Eastern Ocean and thought of his master, and stopped a long while before going on.','claim.v0330.xyj_white_bone.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch27_31.7','storyver.chinese.xiyouji_ch27_31',7,'黑松林与波月洞','The Black Pine Forest and the Moon-Wave Cave','唐僧把悟空赶走以后，让八戒做了引马的，沙僧挑着担子，往西走去，来到一片黑松林。','With Wukong gone, Bajie led the horse and Sha carried the load.','claim.v0330.xyj_white_bone.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch27_31.8','storyver.chinese.xiyouji_ch27_31',8,'百花羞公主的书信','Princess Baihuaxiu''s letter','三藏被绑在洞里，正在哀哭，忽然一个女子走进来，问他：长老，你从哪里来，为何被他缚在此处？','As Sanzang wept in his bonds, a woman came to him: she was Baihuaxiu, ''Shy of a Hundred Flowers'', third princess of the kingdom of Baoxiang three hundred li to the west, carried off by the demon thirteen years earlier on a mid-autumn night while admiring the moon, and forced to be his wife and bear his children.','claim.v0330.xyj_white_bone.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch27_31.9','storyver.chinese.xiyouji_ch27_31',9,'宝象国的救兵','Rescuers from Baoxiang','师徒三人来到宝象国，三藏到朝门外倒换关文，拜见国王，把公主的书信呈上。','In Baoxiang Sanzang presented the letter, and the king and the whole palace wept to read his lost daughter''s hand.','claim.v0330.xyj_white_bone.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch27_31.10','storyver.chinese.xiyouji_ch27_31',10,'唐僧变成老虎','Tang Sanzang turned into a tiger','那妖魔哄好了公主，又起了一个毒计。','Having soothed his wife, the demon devised a poisonous plan.','claim.v0330.xyj_white_bone.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch27_31.11','storyver.chinese.xiyouji_ch27_31',11,'白龙马化作宫娥','The dragon horse as a palace maid','这件事传到了御马监，那匹白龙马听得明白，心想：我师父分明是个好人，被这妖精变作老虎，大师兄被赶走了，八戒、沙僧又不见回来，我若不去救他，这功果休矣！','In the imperial stables the White Dragon Horse heard the news.','claim.v0330.xyj_white_bone.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch27_31.12','storyver.chinese.xiyouji_ch27_31',12,'八戒义激猴王','Bajie goads the Monkey King','八戒驾云来到花果山，只见悟空坐在高崖石上，千百个猴子围着他，口里喊着“大圣爷爷”。','On the Mountain of Flowers and Fruit Bajie found Wukong enthroned among a thousand monkeys.','claim.v0330.xyj_white_bone.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch27_31.13','storyver.chinese.xiyouji_ch27_31',13,'悟空变公主','Wukong as the princess','悟空和八戒先到碗子山波月洞，悟空对八戒说：你先把沙僧救出来，我去对付那妖精。','At the Moon-Wave Cave Wukong sent Bajie and Sha to rescue each other and take the princess home, and he hurled the demon''s two children down from the sky onto the palace steps of Baoxiang.','claim.v0330.xyj_white_bone.13',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch27_31.14','storyver.chinese.xiyouji_ch27_31',14,'天上少了一位星宿','A star missing from heaven','悟空四处寻找不见，心想：这妖精若是地上的，我老孙的火眼金睛断不会找不到他；莫非他是天上来的？','Unable to find the demon on earth, Wukong guessed he came from heaven and asked the Jade Emperor to check the rolls.','claim.v0330.xyj_white_bone.14',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch27_31.15','storyver.chinese.xiyouji_ch27_31',15,'师徒重逢','Master and disciple reconciled','悟空回到宝象国，公主已经被八戒、沙僧送回宫中，一家团圆，国王设宴答谢。','Back in Baoxiang the princess had been restored to her family, but Sanzang still crouched in the cage as a tiger.','claim.v0330.xyj_white_bone.15',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch56_58.1','storyver.chinese.xiyouji_ch56_58',1,'草寇拦路','Highwaymen on the road','唐僧师徒离开西梁女国，又往西行，正值夏天，熏风初动，梅雨丝丝。','Beyond the Women''s Kingdom, in early summer, Sanzang rode ahead and was stopped by thirty highwaymen who tied him to a tree to wait for his disciples.','claim.v0330.xyj_two_monkeys.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch56_58.2','storyver.chinese.xiyouji_ch56_58',2,'杨老儿的儿子','The old man''s son','天色将晚，师徒来到一户人家借宿。','That evening the old man Yang and his wife fed and lodged them, and he sighed that his only son was a robber and arsonist who had been gone five days.','claim.v0330.xyj_two_monkeys.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch56_58.3','storyver.chinese.xiyouji_ch56_58',3,'又一次被逐','Banished again','三藏一见那颗人头，吓得跌下马来，大骂：这个泼猢狲，唬杀我也！','At the sight of the head Sanzang fell from his horse, crying to take it away; Bajie kicked it off the road and buried it.','claim.v0330.xyj_two_monkeys.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch56_58.4','storyver.chinese.xiyouji_ch56_58',4,'无处可去的猴王','A monkey king with nowhere to go','悟空被师父赶走，一阵筋斗翻到半空，独自闷闷不乐，心想：我还是回花果山水帘洞吧？','Banished, Wukong could think of nowhere to go: the monkeys would laugh at him at home, heaven would not keep him long, his immortal friends would see his shame, and he hated begging at the dragon palaces.','claim.v0330.xyj_two_monkeys.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch56_58.5','storyver.chinese.xiyouji_ch56_58',5,'假行者打倒唐僧','A false Wukong strikes down the master','再说唐僧赶走了悟空，叫八戒引马、沙僧挑担，往西走了五十里，口渴难忍，叫八戒去化些水来。','With Wukong gone, Sanzang sent Bajie for water and then Sha to find Bajie.','claim.v0330.xyj_two_monkeys.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch56_58.6','storyver.chinese.xiyouji_ch56_58',6,'沙僧上花果山','Sha Wujing at the Mountain of Flowers and Fruit','沙僧驾云往东走了三昼夜，才到东洋大海，又过了海，来到花果山。','After three days and nights Sha reached the Mountain of Flowers and Fruit and found Wukong on a stone throne among his monkeys, reading aloud, over and over, the Tang emperor''s travel rescript.','claim.v0330.xyj_two_monkeys.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch56_58.7','storyver.chinese.xiyouji_ch56_58',7,'落伽山上的真行者','The real Wukong at Potalaka','沙僧来到落伽山，见了观音菩萨，正要把事情说出来，猛抬头，只见孙悟空站在菩萨身旁！','At Potalaka Sha found Wukong standing beside Guanyin and swung his staff at him, but Guanyin stopped him.','claim.v0330.xyj_two_monkeys.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch56_58.8','storyver.chinese.xiyouji_ch56_58',8,'两个孙悟空','Two Sun Wukongs','两人来到花果山，果然看见一个行者高坐石台之上，与群猴饮酒作乐，模样与悟空一般无二：也是黄发金箍，金睛火眼；身穿也是锦布直裰，腰系虎皮裙；手中也拿一条金箍铁棒，足下也踏一双麂皮靴；也是这等毛脸雷公嘴，朔腮别土星，查耳额颅阔，獠牙向外生。','On the mountain sat a Wukong drinking with the monkeys, identical in every detail — golden band, fiery eyes, tiger-skin kilt, iron rod, deerskin boots, hairy thunder-god face.','claim.v0330.xyj_two_monkeys.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch56_58.9','storyver.chinese.xiyouji_ch56_58',9,'南海与天宫都分不清','Neither the Southern Sea nor heaven can tell','两个行者一路打到落伽山，惊动了诸天神将，围住两人。','At Potalaka the guardian deities surrounded the two fighters.','claim.v0330.xyj_two_monkeys.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch56_58.10','storyver.chinese.xiyouji_ch56_58',10,'唐僧念咒，地府查问','The master''s spell and the registers of the dead','唐僧在一户人家借宿等候，忽听得空中吵嚷，八戒抬头一看，说：师父，两个师兄打来了！','Sanzang was lodging with a family when the two Wukongs came brawling out of the sky.','claim.v0330.xyj_two_monkeys.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch56_58.11','storyver.chinese.xiyouji_ch56_58',11,'谛听','Diting the listener','正说着，地藏王菩萨说：且住，且住。','Then Kṣitigarbha said to wait: his beast Diting, who lay beneath his sutra table, could listen to the whole world, all creatures and immortals, and tell good from bad.','claim.v0330.xyj_two_monkeys.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch56_58.12','storyver.chinese.xiyouji_ch56_58',12,'雷音寺：四种猴子','Thunderclap Monastery: four kinds of monkey','如来正在灵山雷音宝刹为四大菩萨、八大金刚、五百阿罗、三千揭谛、比丘尼、优婆塞、优婆夷诸大众说法，讲到“不有中有，不无中无；不色中色，不空中空”，忽见两个行者一路打来，众大众都慌了。','The Buddha was preaching to his whole assembly at Thunderclap Monastery when the two Wukongs came fighting in.','claim.v0330.xyj_two_monkeys.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch56_58.13','storyver.chinese.xiyouji_ch56_58',13,'一棒定真假','One blow settles it','那六耳猕猴听见如来说出他的本相，胆战心惊，急纵身跳起来就要逃走。','Hearing his true name, the macaque leapt to flee; the whole assembly closed round, and he turned into a bee and flew up — but the Buddha tossed his golden alms bowl into the air and it came down over the bee.','claim.v0330.xyj_two_monkeys.13',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch59_61.1','storyver.chinese.xiyouji_ch59_61',1,'秋天里的热浪','A heat wave in autumn','师徒四众收了心猿，同心戮力，赶奔西天。','Autumn came, but the road grew hotter instead of cooler.','claim.v0330.xyj_fan.01',NULL,'place.chinese.flaming_mountains_xiyouji','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch59_61.2','storyver.chinese.xiyouji_ch59_61',2,'芭蕉扇的来历','The plantain fan','悟空问：铁扇仙是谁？','The Iron Fan Immortal had a plantain fan, the old man said: one wave put out the fire, a second raised wind, a third brought rain, and then the people could sow and harvest.','claim.v0330.xyj_fan.02',NULL,'place.chinese.flaming_mountains_xiyouji','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch59_61.3','storyver.chinese.xiyouji_ch59_61',3,'一调：罗刹女的十几剑','First try: a dozen sword strokes','悟空来到芭蕉洞前，只见洞门紧闭，外面风景秀丽。','At the Plantain Cave Wukong politely asked to borrow the fan.','claim.v0330.xyj_fan.03',NULL,'place.chinese.flaming_mountains_xiyouji','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch59_61.4','storyver.chinese.xiyouji_ch59_61',4,'一扇五万里','Fanned fifty thousand li','罗刹女说：我的宝贝原不轻借。','Refused, Wukong swung his rod, and they fought until dusk.','claim.v0330.xyj_fan.04',NULL,'place.chinese.flaming_mountains_xiyouji','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch59_61.5','storyver.chinese.xiyouji_ch59_61',5,'钻进肚里讨扇','Inside her belly','悟空来到洞前，又叫：开门，开门！','Back at the cave, Wukong stood unmoved through three waves of the fan; the Rākṣasī fled inside and barred the door.','claim.v0330.xyj_fan.05',NULL,'place.chinese.flaming_mountains_xiyouji','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch59_61.6','storyver.chinese.xiyouji_ch59_61',6,'假扇子越扇越旺','The false fan feeds the fire','悟空拿着扇子，驾云回到红瓦房，把扇子给师父看，三藏又惊又喜。','Delighted, the pilgrims set out, but forty li on the ground was so hot that Bajie''s trotters burned.','claim.v0330.xyj_fan.06',NULL,'place.chinese.flaming_mountains_xiyouji','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch59_61.7','storyver.chinese.xiyouji_ch59_61',7,'火焰山的来历','How the Flaming Mountains began','土地说：这火原是大圣放的。','The fire, said the earth god, was Wukong''s own doing.','claim.v0330.xyj_fan.07',NULL,'place.chinese.flaming_mountains_xiyouji','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch59_61.8','storyver.chinese.xiyouji_ch59_61',8,'积雷山的玉面公主','The Jade-Faced Princess of Thunder Mountain','悟空驾云来到积雷山，只见那山峻险，满山的松柏。','On Thunder Mountain Wukong met a beautiful woman picking orchids — the Jade-Faced Princess.','claim.v0330.xyj_fan.08',NULL,'place.chinese.flaming_mountains_xiyouji','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch59_61.9','storyver.chinese.xiyouji_ch59_61',9,'碧波潭的宴席','A feast in the Green Wave Pool','正斗到难解难分之时，山峰上有人叫道：牛爷爷，我大王多多拜上，幸赐早临，好安座也。','In the middle of the fight a messenger called from the peak: his king awaited the Bull Demon King at a banquet.','claim.v0330.xyj_fan.09',NULL,'place.chinese.flaming_mountains_xiyouji','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch59_61.10','storyver.chinese.xiyouji_ch59_61',10,'二调：变作牛魔王','Second try: Wukong as the Bull Demon King','悟空变的牛魔王来到芭蕉洞前，叫开了门，女童们见是大王回来了，都跑进去报告：奶奶，爷爷来家了！','The maids ran in to announce the master''s return, and the Rākṣasī hurried out to welcome her husband, not doubting him for a moment.','claim.v0330.xyj_fan.10',NULL,'place.chinese.flaming_mountains_xiyouji','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch59_61.11','storyver.chinese.xiyouji_ch59_61',11,'只会变大，不会变小','It grows, but will not shrink','悟空接在手中，却又不信，暗想：这么一个小小的东西，怎么扇得息火焰？','Unsure such a tiny thing could quench eight hundred li of fire, the false bull asked.','claim.v0330.xyj_fan.11',NULL,'place.chinese.flaming_mountains_xiyouji','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch59_61.12','storyver.chinese.xiyouji_ch59_61',12,'牛魔王变八戒','The Bull Demon King as Bajie','牛魔王在碧波潭散了宴席，出来一看，辟水金睛兽不见了，心知是悟空偷去，变作他的模样去骗罗刹女了。','Coming out of the Green Wave Pool to find his beast gone, the Bull Demon King knew what had happened, and the weeping Rākṣasī confirmed it.','claim.v0330.xyj_fan.12',NULL,'place.chinese.flaming_mountains_xiyouji','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch59_61.13','storyver.chinese.xiyouji_ch59_61',13,'天上地下的大围捕','Heaven and earth close in','悟空和牛魔王又在山前大战起来。','The fight resumed, and now Bajie arrived with the earth god and his ghost soldiers.','claim.v0330.xyj_fan.13',NULL,'place.chinese.flaming_mountains_xiyouji','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.chinese_xiyouji_ch59_61.14','storyver.chinese.xiyouji_ch59_61',14,'三调：四十九扇灭火','Third try: forty-nine waves','罗刹女听见丈夫在外面哀叫，急忙卸了钗环，脱了色服，挽青丝如道姑，穿缟素似比丘，双手捧着那柄丈二长短的芭蕉扇子，走出门来，跪在地下磕头说：望菩萨饶我夫妻之命，愿将此扇奉承孙叔叔成功去也！','Hearing her husband''s cries, the Rākṣasī took off her jewels, put on plain clothes like a nun and knelt with the twelve-foot fan, offering it to ''Uncle Sun'' if their lives were spared.','claim.v0330.xyj_fan.14',NULL,'place.chinese.flaming_mountains_xiyouji','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book1.1','storyver.hindu.ramayana_griffith_book1',1,'一对麻鹬与第一首输洛迦','Two curlews and the first śloka','苦行者蚁垤住在多摩萨河边的净修林里。','The ascetic Vālmīki asked the visiting sage Nārada whether any man on earth was virtuous, brave, grateful, truthful, kind to all creatures, learned, handsome, self-controlled and feared even by the gods in battle.','claim.v0330.ram_bala.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book1.2','storyver.hindu.ramayana_griffith_book1',2,'两个孩子吟唱史诗','Two boys sing the epic','蚁垤闭目静坐，以瑜伽的力量看见了罗摩一生的全部经过，就像看见手掌心里的一颗庵摩罗果一样清楚。','Seated in meditation, Vālmīki saw Rāma''s whole life as clearly as a fruit in his palm, and composed it in twenty-four thousand verses, six books and an Uttara.','claim.v0330.ram_bala.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','俱舍与罗婆是罗摩之子，这一点要到后篇（第七卷）才说明，本系列不讲第七卷。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book1.3','storyver.hindu.ramayana_griffith_book1',3,'阿逾陀城与无子的国王','Ayodhyā and a childless king','萨罗逾河畔有一个富庶的国家叫憍萨罗，国都就是阿逾陀。','On the Sarayū lay the rich land of Kosala and its capital Ayodhyā, twelve leagues long, its broad streets sprinkled with water and strewn with flowers, its walls high and its moats deep, full of palaces, gardens and mango groves, merchants and musicians; no one there was poor, unlettered or godless.','claim.v0330.ram_bala.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book1.4','storyver.hindu.ramayana_griffith_book1',4,'从未见过女人的鹿角仙人','Ṛṣyaśṛṅga, who had never seen a woman','苏曼多罗讲起了那个预言：迦叶波仙人有个儿子名叫毗槃陀迦，毗槃陀迦又有一个儿子，名叫鹿角。','Sumantra told the story: Ṛṣyaśṛṅga, son of Vibhāṇḍaka, had grown up in the forest tending the sacred fire and had never seen anyone but his father, nor knew that women existed.','claim.v0330.ram_bala.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book1.5','storyver.hindu.ramayana_griffith_book1',5,'众神的请求','The gods'' petition','春天到了，十车王在萨罗逾河北岸搭起祭坛，举行盛大的马祭。','In spring Daśaratha held the great horse sacrifice by the Sarayū, and then Ṛṣyaśṛṅga led a rite for sons.','claim.v0330.ram_bala.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book1.6','storyver.hindu.ramayana_griffith_book1',6,'四位王子的诞生','The birth of four princes','求子祭祀的圣火熊熊燃起，从火中走出一位光芒万丈的神灵，他身穿红衣，声如鼓鸣，双手捧着一只盖着银盖的金碗，碗里盛满了天界的乳粥。','From the sacrificial fire rose a radiant being in red, with a voice like a drum, carrying a golden bowl of heavenly rice-milk under a silver lid, sent by the Lord of Creatures for the queens.','claim.v0330.ram_bala.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book1.7','storyver.hindu.ramayana_griffith_book1',7,'众友仙人的请求','Viśvāmitra''s request','王子们快到十六岁时，十车王正和大臣们商量为他们娶亲，门卫来报：大仙人众友到了。','As the princes neared sixteen, the great sage Viśvāmitra arrived, and Daśaratha promised to grant whatever he asked.','claim.v0330.ram_bala.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book1.8','storyver.hindu.ramayana_griffith_book1',8,'恒河边的夜宿与多吒迦','Nights by the Ganges and Tāṭakā','众友带着两位王子上路，走了一由旬半，来到萨罗逾河南岸。','On the bank of the Sarayū Viśvāmitra taught Rāma the spells Balā and Atibalā, which banished fatigue and fever and made him unmatched in strength and wisdom; the princes slept their first night away from the palace on grass.','claim.v0330.ram_bala.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book1.9','storyver.hindu.ramayana_griffith_book1',9,'神兵与圆满的祭祀','Divine weapons and the completed sacrifice','众友对罗摩十分满意，说：我把我所知道的一切神兵都传给你，有了它们，你能战胜天神、阿修罗、乾闼婆和那伽。','Pleased, Viśvāmitra gave Rāma every divine weapon he knew — the discuses of Dharma, Time and Vishnu, Indra''s thunderbolt, Śiva''s trident, Brahmā''s weapon, the nooses of Dharma, Time and Varuṇa, and weapons that cause sleep, bewilderment and fever.','claim.v0330.ram_bala.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book1.10','storyver.hindu.ramayana_griffith_book1',10,'恒河从天而降','The descent of the Ganges','众友带着王子们前往弥提罗，途中在恒河岸边歇息，罗摩问起这条三界之河的来历，众友便讲述了恒河下凡的故事。','On the way to Mithilā, resting by the Ganges, Viśvāmitra told how the river came down.','claim.v0330.ram_bala.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book1.11','storyver.hindu.ramayana_griffith_book1',11,'众友仙人的苦修','How Viśvāmitra became a brahmin sage','到了弥提罗，国王遮那竭的祭司舍多难陀向罗摩讲述了众友仙人自己的往事。','At Mithilā Janaka''s priest Śatānanda told Rāma about Viśvāmitra.','claim.v0330.ram_bala.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book1.12','storyver.hindu.ramayana_griffith_book1',12,'阿诃厘耶的解脱','Ahalyā released','在去弥提罗的路上，他们经过一座荒废的净修林，林中寂静无声，一个人影也没有。','On the way to Mithilā they passed a silent, deserted hermitage.','claim.v0330.ram_bala.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','阿诃厘耶是否认出因陀罗、她受的是什么形式的诅咒，各个版本和后世传统说法不一；这里只依格里菲斯所据的通行本讲述。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book1.13','storyver.hindu.ramayana_griffith_book1',13,'湿婆的大弓','The bow of Śiva','他们来到弥提罗，国王遮那竭正在举行祭祀，热情地迎接了众友和两位王子，问：这两位像天神一样的少年是谁？','At Mithilā King Janaka welcomed them and told the story of his famous bow: Śiva had once raised it in anger against the gods at Dakṣa''s sacrifice and later left it with Janaka''s ancestors.','claim.v0330.ram_bala.13',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book1.14','storyver.hindu.ramayana_griffith_book1',14,'四场婚礼与持斧罗摩','Four weddings and Paraśurāma','遮那竭派使者快马加鞭赶到阿逾陀，十车王带着大军和亲属来到弥提罗。','Daśaratha came with his army, and the four brothers were married on one day: Rāma to Sītā, Lakṣmaṇa to her sister Ūrmilā, Bharata and Śatrughna to Māṇḍavī and Śrutakīrti, daughters of Janaka''s brother.','claim.v0330.ram_bala.14',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book2.1','storyver.hindu.ramayana_griffith_book2',1,'立太子的消息','News of the consecration','十车王渐渐老了，他看见天上出现不祥的征兆，心想：趁我还在世，应该立罗摩为太子。','Growing old and seeing ill omens, Daśaratha resolved to make Rāma his heir while he lived.','claim.v0330.ram_ayodhya.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book2.2','storyver.hindu.ramayana_griffith_book2',2,'驼背的曼他罗','The hunchbacked Mantharā','王后吉迦伊有一个从娘家带来的侍女，名叫曼他罗，是个驼背。','Queen Kaikeyī''s hunchbacked maid Mantharā, who had come with her from her father''s house, saw the city decorated from the palace terrace and learned that Rāma was to be consecrated next day.','claim.v0330.ram_ayodhya.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book2.3','storyver.hindu.ramayana_griffith_book2',3,'愤怒之室','The chamber of wrath','曼他罗教她：你脱下首饰，换上旧衣，躺在愤怒之室的地上，不要理睬国王。','Mantharā told her what to do: take off her jewels, put on old clothes and lie on the floor of the chamber of wrath; the doting king would grant anything; she must demand Bharata''s consecration and Rāma''s exile to the Daṇḍaka forest for fourteen years, by which time Bharata would be secure.','claim.v0330.ram_ayodhya.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book2.4','storyver.hindu.ramayana_griffith_book2',4,'国王的长夜','The king''s long night','十车王听了，像被老虎惊吓的鹿一样，坐在地上发抖，叹了一口气，昏倒过去。','The king trembled like a deer that sees a tiger and fainted.','claim.v0330.ram_ayodhya.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book2.5','storyver.hindu.ramayana_griffith_book2',5,'面不改色','Without a change of face','罗摩穿着节日的盛装，坐着车子来到父亲宫中，沿途百姓欢呼祝福。','Rāma came in festive dress through cheering streets and found his father haggard, able only to say ''Rāma!'' and weep.','claim.v0330.ram_ayodhya.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book2.6','storyver.hindu.ramayana_griffith_book2',6,'憍萨厘雅的眼泪与罗什曼那的怒火','Kausalyā''s tears and Lakṣmaṇa''s anger','憍萨厘雅正在为儿子的灌顶向天神祈祷，看见罗摩进来，欢喜地上前拥抱他。','Kausalyā was praying for her son''s consecration when he told her he must go to the forest for fourteen years.','claim.v0330.ram_ayodhya.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book2.7','storyver.hindu.ramayana_griffith_book2',7,'悉多的回答','Sītā''s answer','罗摩来到自己的宫中，悉多正满心欢喜地等着他，见他神色异样，惊问出了什么事。','Sītā was waiting joyfully when Rāma came and told her everything: she should stay, serve his parents, honour Bharata and not praise Rāma before him, since kings dislike hearing others praised.','claim.v0330.ram_ayodhya.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book2.8','storyver.hindu.ramayana_griffith_book2',8,'树皮衣','Bark garments','罗什曼那也来到罗摩面前，含着眼泪说：哥哥，如果你一定要去森林，我就拿着弓走在你前面开路。','Lakṣmaṇa vowed to walk before Rāma with his bow: without him he wanted neither heaven nor immortality.','claim.v0330.ram_ayodhya.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book2.9','storyver.hindu.ramayana_griffith_book2',9,'出城与渡恒河','Leaving the city and crossing the Ganges','苏曼多罗驾着车子，载着罗摩、悉多和罗什曼那出了宫门。','Sumantra drove them out of the palace with the whole city weeping behind; the king and Kausalyā ran barefoot after the chariot calling ''Stop!'', but Rāma told Sumantra to drive on and say he had not heard.','claim.v0330.ram_ayodhya.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book2.10','storyver.hindu.ramayana_griffith_book2',10,'质多罗俱吒山','Mount Citrakūṭa','三人渡过恒河，走进森林。','That first night in the forest Rāma for once showed grief: his father would not sleep, and Kaikeyī, triumphant, might mistreat his mother — Lakṣmaṇa should go back to care for them.','claim.v0330.ram_ayodhya.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book2.11','storyver.hindu.ramayana_griffith_book2',11,'十车王之死','The death of Daśaratha','苏曼多罗驾着空车回到阿逾陀，满城的人看见车上没有罗摩，都哭了起来。','When Sumantra returned with an empty chariot the city wailed and the king fainted again.','claim.v0330.ram_ayodhya.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','那位少年苦行者在后世传统中常被叫做“室罗波那”（Śravaṇa），蚁垤本里没有给出这个名字。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book2.12','storyver.hindu.ramayana_griffith_book2',12,'婆罗多归国','Bharata comes home','国王去世以后，大臣们把他的遗体泡在油槽里保存，派使者快马去请远在舅舅家的婆罗多，嘱咐使者不要告诉他发生了什么。','The ministers preserved the king''s body in a vat of oil and sent riders for Bharata without telling him why.','claim.v0330.ram_ayodhya.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book2.13','storyver.hindu.ramayana_griffith_book2',13,'进山请兄','To bring his brother back','葬礼过后，大臣们请婆罗多登基。','Asked to take the throne, Bharata declared that it belonged to Rāma: he would bring Rāma back and go into exile himself.','claim.v0330.ram_ayodhya.13',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book2.14','storyver.hindu.ramayana_griffith_book2',14,'山中相会','Meeting on the mountain','质多罗俱吒山上，罗摩正和悉多在山间漫步，忽然尘土飞扬，大地震动，林中的鸟兽四散奔逃。','On Citrakūṭa dust rose and the beasts fled.','claim.v0330.ram_ayodhya.14',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book2.15','storyver.hindu.ramayana_griffith_book2',15,'阇波厘的论辩','The argument of Jābāli','第二天，婆罗多当着众人的面恳求罗摩：哥哥，王国本来就属于你。','Before the whole assembly Bharata begged Rāma to return and be consecrated, and the army and citizens knelt with him.','claim.v0330.ram_ayodhya.15',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book2.16','storyver.hindu.ramayana_griffith_book2',16,'一双鞋子与南迪村','A pair of sandals and Nandigrāma','婆罗多见罗摩不肯回去，就躺在草屋前的地上，说：我要像债主一样躺在这里绝食，直到哥哥答应回去为止。','When Rāma would not yield, Bharata lay down before the hut to fast like a creditor; Rāma said a kṣatriya should not do this, and sages in the sky told Bharata to accept Rāma''s resolve.','claim.v0330.ram_ayodhya.16',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book3.1','storyver.hindu.ramayana_griffith_book3',1,'弹宅迦林中的誓言','A vow in the Daṇḍaka forest','罗摩三人走进茫茫的弹宅迦林，看见林中散布着许多仙人的净修林，林中挂着树皮衣，祭火熊熊，鹿群安静地吃草，鸟儿在枝头歌唱。','In the Daṇḍaka forest hermitages lay among grazing deer and sacred fires, and the hermits begged Rāma, as a king even in exile, to protect them from the man-eating rākṣasas whose victims'' bones lay scattered around.','claim.v0330.ram_aranya.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book3.2','storyver.hindu.ramayana_griffith_book3',2,'悉多论杀生','Sītā on violence','他们又拜访了舍罗槃伽仙人，看见因陀罗乘着天车来迎接这位仙人升天；仙人把自己修来的天界送给罗摩，然后投入火中，化作一个光辉的少年升天而去。','They saw Indra come in his chariot for the sage Śarabhaṅga, who gave Rāma the worlds he had won, entered the fire and rose as a radiant youth.','claim.v0330.ram_aranya.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book3.3','storyver.hindu.ramayana_griffith_book3',3,'投山仙人与五树林','Agastya and Pañcavaṭī','此后十年，罗摩三人在弹宅迦林中的各个净修林之间来来往往，有时住一个月，有时住一年，日子过得平静安宁。','For ten years they moved peacefully among the hermitages, staying a month here, a year there.','claim.v0330.ram_aranya.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book3.4','storyver.hindu.ramayana_griffith_book3',4,'首哩薄那迦','Śūrpaṇakhā','有一天，罗摩坐在草屋前和悉多、罗什曼那说话，一个女罗刹偶然经过，看见了他。','One day Rāvaṇa''s sister Śūrpaṇakhā — pot-bellied, squint-eyed and harsh-voiced — passed the hut and was smitten by the handsome, lotus-eyed Rāma.','claim.v0330.ram_aranya.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book3.5','storyver.hindu.ramayana_griffith_book3',5,'一人对一万四千','One against fourteen thousand','伽罗见妹妹满脸是血，大怒，派了十四个罗刹去杀罗摩兄弟。','Khara sent fourteen rākṣasas, and Rāma''s fourteen arrows pierced their hearts.','claim.v0330.ram_aranya.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book3.6','storyver.hindu.ramayana_griffith_book3',6,'罗波那被激怒','Rāvaṇa is roused','一个名叫阿甘波那的罗刹从战场上逃了出来，飞到楞伽城报告罗波那：伽罗、突舍那和一万四千大军都被十车王的儿子罗摩一个人消灭了！','The rākṣasa Akampana fled to Laṅkā and told Rāvaṇa that one man had destroyed Khara''s army.','claim.v0330.ram_aranya.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book3.7','storyver.hindu.ramayana_griffith_book3',7,'摩哩遮的劝告','Mārīca''s warning','罗波那又坐着飞车越过大海，来到摩哩遮的净修林。','Rāvaṇa flew over the sea to Mārīca, now living as an ascetic in bark and matted hair, and told him the plan: become a golden deer, lure Rāma and Lakṣmaṇa away, and Rāvaṇa would seize Sītā.','claim.v0330.ram_aranya.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book3.8','storyver.hindu.ramayana_griffith_book3',8,'金色的鹿','The golden deer','两人来到五树林附近，摩哩遮变成了一只奇异的鹿：它的角尖像蓝宝石，脸上有白色和黑色的斑点，嘴像红莲花，耳朵像蓝色的莲花，脖子高挺，肚腹像蓝宝石一样发亮，身上闪耀着金银交织的光彩，四只蹄子像青金石。','Near Pañcavaṭī Mārīca became a marvellous deer: sapphire-tipped horns, a face dappled white and black, a mouth like a red lotus, a belly glowing like sapphire, a body shimmering with gold and silver, hooves of lapis.','claim.v0330.ram_aranya.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book3.9','storyver.hindu.ramayana_griffith_book3',9,'“啊，悉多！啊，罗什曼那！”','''Ah Sītā! Ah Lakṣmaṇa!''','那只金鹿时隐时现，时远时近，把罗摩引得越来越远，离开草屋很远很远。','The deer led Rāma far away, now appearing, now vanishing, until in anger he loosed a flaming arrow of Brahmā into its heart.','claim.v0330.ram_aranya.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book3.10','storyver.hindu.ramayana_griffith_book3',10,'扮作苦行者的罗波那','Rāvaṇa disguised as an ascetic','罗什曼那刚走，罗波那就变成一个云游的婆罗门苦行者，穿着橘黄色的袍子，头上结着发髻，手里拿着伞和水罐，走到草屋前。','As soon as Lakṣmaṇa left, Rāvaṇa came to the hut as a wandering brahmin in ochre with matted hair, umbrella and water-pot; the trees stopped stirring, the wind dropped and the Godāvarī slowed.','claim.v0330.ram_aranya.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book3.11','storyver.hindu.ramayana_griffith_book3',11,'鹫王阇吒优私的战斗','Jaṭāyu''s fight','罗波那听了大怒，现出原形：十个头，二十只手臂，身穿红衣，像一座黑山。','Rāvaṇa showed his true form — ten heads, twenty arms, red-robed like a black mountain — seized Sītā by the hair and legs, set her in his golden ass-drawn chariot and rose into the sky while she called on Rāma, Lakṣmaṇa, the trees, the Godāvarī and the beasts to tell Rāma who had taken her.','claim.v0330.ram_aranya.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book3.12','storyver.hindu.ramayana_griffith_book3',12,'无忧树林中的期限','A deadline in the aśoka grove','罗波那抱着悉多飞越森林和高山，悉多的首饰一件件掉落，她头上的花瓣像雨点一样飘下。','Flying over forests and mountains, Sītā let her ornaments and flower petals fall, and seeing five monkeys on a peak she dropped her golden scarf with her jewels tied in it, hoping they would tell Rāma.','claim.v0330.ram_aranya.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book3.13','storyver.hindu.ramayana_griffith_book3',13,'空荡荡的草屋','The empty hut','罗摩在回来的路上遇见了罗什曼那，大吃一惊：你怎么把悉多一个人留下了？','On the way back Rāma met Lakṣmaṇa and reproached him for leaving Sītā over angry words.','claim.v0330.ram_aranya.13',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book3.14','storyver.hindu.ramayana_griffith_book3',14,'迦槃陀与舍波哩','Kabandha and Śabarī','兄弟二人继续向南寻找，走进一片阴森的森林，忽然被一双长臂抓住。','Going south through a gloomy forest, the brothers were seized by long arms: Kabandha, a headless monster with a mouth in his belly, one eye in his chest and arms a league long.','claim.v0330.ram_aranya.14',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book4.1','storyver.hindu.ramayana_griffith_book4',1,'般波湖的春天','Spring at Lake Pampā','罗摩和罗什曼那来到般波湖边。','They reached Lake Pampā in spring: clear water, lotuses in bloom, bees humming, birds singing in pairs, aśoka and karṇikāra trees aflame with red and yellow flowers.','claim.v0330.ram_kishkindha.01',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book4.2','storyver.hindu.ramayana_griffith_book4',2,'扮作苦行者的哈奴曼','Hanumān in an ascetic''s guise','哩舍牟迦山上，须羯哩婆和他的四个大臣正坐着，远远看见两个手持弓箭、身材高大的人走来，吓得跳起来，以为是哥哥波林派来杀他的。','On Mount Ṛśyamūka Sugrīva and his four ministers saw two tall armed men coming and leapt up in fear that Vālin had sent them.','claim.v0330.ram_kishkindha.02',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book4.3','storyver.hindu.ramayana_griffith_book4',3,'火前结盟与悉多的首饰','A pact before the fire and Sītā''s ornaments','哈奴曼取来两块木头，钻出火来，点燃了一堆圣火。','Hanumān kindled a sacred fire from two sticks, and Rāma and Sugrīva walked around it and swore friendship: one friend''s friends and foes would be the other''s.','claim.v0330.ram_kishkindha.03',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book4.4','storyver.hindu.ramayana_griffith_book4',4,'须羯哩婆的往事','Sugrīva''s story','罗摩问起须羯哩婆为什么被哥哥赶出来，须羯哩婆讲了自己的往事。','Asked why he was exiled, Sugrīva told his story.','claim.v0330.ram_kishkindha.04',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book4.5','storyver.hindu.ramayana_griffith_book4',5,'杜度毗的骨头与七棵娑罗树','Dundubhi''s bones and seven sāl trees','须羯哩婆讲完，又担心地说：罗摩，波林的力量太大了。','Sugrīva still worried: Vālin leapt every dawn from the western to the eastern sea and the southern to the northern, tossed mountain peaks like balls, and had killed the buffalo-demon Dundubhi with the strength of a thousand elephants, flinging its corpse a league so that its blood spattered a sage''s hermitage — hence the curse.','claim.v0330.ram_kishkindha.05',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book4.6','storyver.hindu.ramayana_griffith_book4',6,'花环与波林之死','The garland and the death of Vālin','须羯哩婆来到基什金达城外，大声吼叫，向波林挑战。','Outside Kiṣkindhā Sugrīva roared his challenge and the brothers fought, but from behind his tree Rāma held his arrow: they were identical, and he feared to hit the wrong one.','claim.v0330.ram_kishkindha.06',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book4.7','storyver.hindu.ramayana_griffith_book4',7,'波林的责问与多罗的哀哭','Vālin''s reproach and Tārā''s lament','波林倒在地上，看见罗摩和罗什曼那走过来，用尽力气责问罗摩：罗摩，你出身高贵，人人都说你仁慈、守信、正直，我和须羯哩婆打斗，你却从背后暗箭伤人，这算什么正法？','Dying, Vālin reproached Rāma: famed for kindness and truth, Rāma had shot him from hiding while he fought another, though Vālin had never wronged him; had Rāma asked, Vālin could have dragged Rāvaṇa to him in a day.','claim.v0330.ram_kishkindha.07',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','罗摩从暗处射杀波林是否合乎正法，在印度传统内部本身就有长久的争论；本站只讲蚁垤本里双方的说法，不作评判。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book4.8','storyver.hindu.ramayana_griffith_book4',8,'雨季','The rains','波林的葬礼过后，须羯哩婆被拥立为基什金达的国王，安伽陀被立为太子。','After the funeral Sugrīva was crowned king of Kiṣkindhā with Aṅgada as heir.','claim.v0330.ram_kishkindha.08',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book4.9','storyver.hindu.ramayana_griffith_book4',9,'罗什曼那闯进猴城','Lakṣmaṇa storms Kiṣkindhā','罗摩看见秋天已经到了，须羯哩婆却毫无动静，心中焦急又愤怒，对罗什曼那说：秋天到了，正是出兵的时候，须羯哩婆却忘了我们。','Seeing autumn come and no sign from Sugrīva, Rāma sent Lakṣmaṇa with a message: the road Vālin took was not yet closed.','claim.v0330.ram_kishkindha.09',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book4.10','storyver.hindu.ramayana_griffith_book4',10,'四路寻找与一枚戒指','Four search parties and a ring','须羯哩婆把猴子们分成四路，派往东、南、西、北四个方向，每一路都由一位大将率领。','Sugrīva divided the monkeys into four armies for the four quarters, each under a great captain, and described the mountains, rivers, kingdoms and seas each would pass as if he had seen them — as indeed he had, fleeing Vālin across the whole earth.','claim.v0330.ram_kishkindha.10',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book4.11','storyver.hindu.ramayana_griffith_book4',11,'迷失在山洞里','Lost in a cave','南路的猴军翻山越岭，寻遍了文底耶山的每一个山洞、每一片森林，却连悉多的影子也没找到。','The southern army searched every cave and forest of the Vindhyas in vain.','claim.v0330.ram_kishkindha.11',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book4.12','storyver.hindu.ramayana_griffith_book4',12,'商波底与阇婆梵','Sampāti and Jāmbavān','就在这时，一只巨大的老鹫从山洞里爬了出来，它没有翅膀，看见满海滩的猴子，高兴地说：真是天赐的食物！','A huge wingless old vulture crawled from a cave and rejoiced at so much food.','claim.v0330.ram_kishkindha.12',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','后世传统常说哈奴曼因仙人诅咒忘了自己的力量，这个说法出自第七卷（后篇），本节不采用。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book5.1','storyver.hindu.ramayana_griffith_book5',1,'跨海一跃','The leap','哈奴曼登上摩亨陀罗山，身体越变越大，他向太阳、因陀罗、梵天、风神行礼，然后用双脚踩住山顶。','On Mount Mahendra Hanumān grew huge, bowed to the sun, Indra, Brahmā and the wind, and pressed down on the summit: rocks split, springs burst out, flowers rained down, beasts roared in their caves and vidyādharas flew up with their wives to watch.','claim.v0330.ram_sundara.01',NULL,'place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book5.2','storyver.hindu.ramayana_griffith_book5',2,'须罗娑与辛悉迦','Surasā and Siṃhikā','众神想考验一下哈奴曼的力量和智慧，就请蛇母须罗娑变成一个可怕的罗刹女，从海中升起，拦住他的去路，说：众神把你赐给我做食物，进我嘴里来吧！','To test him the gods sent Surasā, mother of serpents, in a rākṣasī''s form to block his path: the gods had given him to her as food.','claim.v0330.ram_sundara.02',NULL,'place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book5.3','storyver.hindu.ramayana_griffith_book5',3,'楞伽城的守护女神','The guardian of Laṅkā','哈奴曼终于看见了海那边的岛屿：岛上有一座三峰山，山顶上就是楞伽城。','Hanumān landed fresh on three-peaked Trikūṭa and looked at Laṅkā: golden walls, jewelled gates, palaces touching the clouds, lotus-filled moats and armed rākṣasas on every wall, like a city of the gods.','claim.v0330.ram_sundara.03',NULL,'place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book5.4','storyver.hindu.ramayana_griffith_book5',4,'月光下的宫殿','Palaces by moonlight','哈奴曼在楞伽城中穿行，月光照亮了街道。','Moonlight lit the streets as Hanumān searched: houses ringing with song, Vedic recitation, drinking and quarrels; guards with one eye or one ear, pot-bellies or humps.','claim.v0330.ram_sundara.04',NULL,'place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book5.5','storyver.hindu.ramayana_griffith_book5',5,'无忧树林中的悉多','Sītā in the aśoka grove','哈奴曼跳过围墙，进入无忧树林。','Hanumān leapt the wall into the flowering aśoka grove and climbed a leafy śiṃśapā tree.','claim.v0330.ram_sundara.05',NULL,'place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book5.6','storyver.hindu.ramayana_griffith_book5',6,'一根草','A blade of grass','天快亮的时候，罗波那带着上百个妻子来到无忧树林，宫女们举着金灯，簇拥着他，他喝得半醉，欲火中烧，径直走到悉多面前。','Near dawn Rāvaṇa came with a hundred wives bearing golden lamps, half drunk and burning with desire.','claim.v0330.ram_sundara.06',NULL,'place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book5.7','storyver.hindu.ramayana_griffith_book5',7,'特哩阇吒的梦','Trijaṭā''s dream','罗波那走后，女罗刹们围住悉多，有的劝她：罗波那是天下最强大的国王，你做他的王后，有享不尽的荣华富贵，何必为了一个穷苦行者受苦？','The rākṣasīs crowded round Sītā, some coaxing her toward the riches of Rāvaṇa''s queen, others brandishing spears and axes and lolling their tongues, one wanting her heart, one her liver, one her blood.','claim.v0330.ram_sundara.07',NULL,'place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book5.8','storyver.hindu.ramayana_griffith_book5',8,'树上唱起罗摩的故事','Rāma''s story sung from the tree','悉多孤零零地坐在树下，绝望之中，她解下自己的长发辫，想用它吊死在树枝上。','Alone and despairing, Sītā loosened her long braid to hang herself from a branch — and then her left eye, arm and thigh began to throb, an auspicious sign for a woman, and her heart steadied.','claim.v0330.ram_sundara.08',NULL,'place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book5.9','storyver.hindu.ramayana_griffith_book5',9,'戒指与髻珠','The ring and the crest-jewel','哈奴曼从树上下来，恭恭敬敬地向悉多行礼，说：您是谁？','Hanumān climbed down and bowed: was she Sītā?','claim.v0330.ram_sundara.09',NULL,'place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book5.10','storyver.hindu.ramayana_griffith_book5',10,'乌鸦的故事','The story of the crow','为了让罗摩确信哈奴曼真的见到了她，悉多又讲了一件只有她和罗摩两个人知道的往事：那时我们住在质多罗俱吒山上，有一天，罗摩累了，枕在我的腿上睡着了。','So that Rāma would be sure, Sītā told a story only the two of them knew.','claim.v0330.ram_sundara.10',NULL,'place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book5.11','storyver.hindu.ramayana_griffith_book5',11,'毁林与被擒','The grove destroyed and Hanumān bound','哈奴曼告别了悉多，心想：我已经找到了悉多，可是还应该看看罗刹们的力量，好回去告诉罗摩。','Having found Sītā, Hanumān resolved to test the rākṣasas'' strength for Rāma.','claim.v0330.ram_sundara.11',NULL,'place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book5.12','storyver.hindu.ramayana_griffith_book5',12,'罗波那殿前','Before Rāvaṇa','哈奴曼被押到罗波那的大殿上。','On his crystal throne under a pearl-studded crown, his eyes blazing in ten heads, Rāvaṇa was so splendid that Hanumān thought that, but for his evil, he might have been a protector of the gods.','claim.v0330.ram_sundara.12',NULL,'place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book5.13','storyver.hindu.ramayana_griffith_book5',13,'火烧楞伽','Laṅkā in flames','罗刹们用旧棉布和破布把哈奴曼的尾巴一圈一圈地缠起来，浇上油，点着了火。','The rākṣasas wrapped his tail in old cotton and rags, soaked it in oil, set it alight and paraded him through the streets with drums — which suited Hanumān, who studied the city''s defences by day.','claim.v0330.ram_sundara.13',NULL,'place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book5.14','storyver.hindu.ramayana_griffith_book5',14,'“我见到悉多了！”','''I have seen Sītā!''','哈奴曼向悉多告别，登上楞伽城外的阿利湿多山，用力一蹬，大山都陷进了地里，他像一片乌云一样飞越大海。','Hanumān pressed Mount Ariṣṭa into the earth as he leapt and flew back like a cloud.','claim.v0330.ram_sundara.14',NULL,'place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book6.1','storyver.hindu.ramayana_griffith_book6',1,'进军南海','The march to the sea','罗摩听完哈奴曼的报告，对他说：你做的事，比任何人都多。','Rāma praised Hanumān but despaired of the sea; Sugrīva urged him not to lose heart.','claim.v0330.ram_yuddha.01','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book6.2','storyver.hindu.ramayana_griffith_book6',2,'罗波那的议事会','Rāvaṇa''s council','楞伽城里，罗波那看着被哈奴曼烧毁的城市，心中又羞又怒，召集大臣们议事：一只猴子就把我的城市烧成这样，罗摩就要带着猴子大军打来了，你们说该怎么办？','In his half-burned city Rāvaṇa asked his council what to do; the ministers boasted that he had beaten Indra, Kubera and Yama, and one of them could eat Rāma''s monkeys alone.','claim.v0330.ram_yuddha.02','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book6.3','storyver.hindu.ramayana_griffith_book6',3,'维毗沙那投奔','Vibhīṣaṇa''s refuge','维毗沙那带着四个随从飞上天空，对罗波那说：哥哥，你被死神迷住了眼睛，听不进忠言。','Telling his brother he was blinded by death, Vibhīṣaṇa flew with four companions across the sea and, hovering over the monkey camp, announced that he sought refuge with Rāma.','claim.v0330.ram_yuddha.03','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book6.4','storyver.hindu.ramayana_griffith_book6',4,'那罗造桥','Nala''s bridge','怎样渡过大海呢？','Vibhīṣaṇa advised Rāma to ask the Ocean''s help, since Sagara''s sons had dug it.','claim.v0330.ram_yuddha.04','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book6.5','storyver.hindu.ramayana_griffith_book6',5,'假头颅与安伽陀出使','A false head and Aṅgada''s embassy','罗波那听说猴军已经过了海，心中惊慌，想出了一条毒计。','Alarmed that the army had crossed, Rāvaṇa had a sorcerer make a head and bow exactly like Rāma''s and told Sītā that his general had beheaded Rāma as he slept on the shore.','claim.v0330.ram_yuddha.05','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book6.6','storyver.hindu.ramayana_griffith_book6',6,'蛇箭与金翅鸟','The serpent arrows and Garuḍa','第二天，大战开始了。','Battle broke out at Laṅkā''s four gates, with trees, rocks and fists against arrows, spears and maces, and champions fought in pairs; Aṅgada beat Indrajit, and Hanumān, Nīla and Sugrīva killed rākṣasa generals.','claim.v0330.ram_yuddha.06','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book6.7','storyver.hindu.ramayana_griffith_book6',7,'唤醒鸠槃羯叻拿','Waking Kumbhakarṇa','罗波那接连损失了几员大将，自己也在战场上被罗摩打得丢盔弃甲——罗摩射断了他的王冠和弓，说：你今天已经累了，回去吧，明天再来和我决战。','Losing general after general, Rāvaṇa himself was beaten on the field: Rāma shot away his crown and bow and told him to go home and rest and come back tomorrow.','claim.v0330.ram_yuddha.07','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book6.8','storyver.hindu.ramayana_griffith_book6',8,'鸠槃羯叻拿之死','The death of Kumbhakarṇa','鸠槃羯叻拿冲进猴军阵中，像一头发狂的大象闯进了芦苇丛。','Kumbhakarṇa waded into the monkeys like a mad elephant into reeds, stuffing them into his mouth — some crawled out of his nose and ears — and mowing hundreds down with his spear, until Aṅgada rallied the fleeing army.','claim.v0330.ram_yuddha.08','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book6.9','storyver.hindu.ramayana_griffith_book6',9,'梵天神兵与药山','The weapon of Brahmā and the mountain of herbs','因陀罗耆又出战了。','After a sacrifice outside the walls gave him an invisible chariot and the weapon of Brahmā, Indrajit loosed it from the sky like a rain of fire, each arrow becoming thousands.','claim.v0330.ram_yuddha.09','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book6.10','storyver.hindu.ramayana_griffith_book6',10,'幻影悉多与因陀罗耆之死','The illusory Sītā and the death of Indrajit','因陀罗耆又想出一条毒计。','Indrajit conjured a woman exactly like Sītā, drove her before the army in his chariot, seized her by the hair and cut her in two before Hanumān''s eyes.','claim.v0330.ram_yuddha.10','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book6.11','storyver.hindu.ramayana_griffith_book6',11,'神矛与药草','The dart and the herbs','罗波那失去了儿子，悲痛得发狂，冲向无忧树林要杀悉多，被一个贤明的大臣拦住：大王，您是学识渊博的人，怎么能杀一个女人？','Mad with grief for his son, Rāvaṇa rushed to kill Sītā until a wise minister reminded him a learned king does not kill a woman; he should turn his rage on Rāma.','claim.v0330.ram_yuddha.11','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','哈奴曼取药山的情节在通行本里出现两次，各本次序不尽相同；本系列按格里菲斯所据通行本的次序分开讲述。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book6.12','storyver.hindu.ramayana_griffith_book6',12,'罗摩与罗波那','Rāma and Rāvaṇa','决战的日子到了。','On the final day the gods judged it unfair that Rāma fought on foot, and Indra sent his charioteer Mātali with his celestial chariot, golden banner, ten green horses and his armour and weapons.','claim.v0330.ram_yuddha.12','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book6.13','storyver.hindu.ramayana_griffith_book6',13,'曼度陀哩的哀哭与新的国王','Mandodarī''s lament and a new king','罗波那的妻子们从城里跑出来，扑在他的尸体上痛哭，王后曼度陀哩哭得最伤心：我的丈夫，你曾经打败过天帝，让三界都害怕你，现在却被一个人杀死了。','Rāvaṇa''s wives poured out to wail over him, Mandodarī most of all: he who had conquered Indra and terrified three worlds had fallen to a man — but she had known Rāma was Vishnu himself; for a woman who did not love him, with so many wives of his own, Rāvaṇa had destroyed himself, his sons, his brother and his kingdom.','claim.v0330.ram_yuddha.13','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book6.14','storyver.hindu.ramayana_griffith_book6',14,'火的考验','The ordeal by fire','维毗沙那派人为悉多沐浴更衣，戴上首饰，用轿子把她抬到罗摩面前。','Bathed and adorned, Sītā was brought in a litter; when guards drove back the crowding monkeys, Rāma had her walk so all could see her — no breach of custom in war or calamity.','claim.v0330.ram_yuddha.14','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','火的考验是今天印度内外讨论最多的情节之一；本节只依通行本讲述双方的话，不作评判。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book6.15','storyver.hindu.ramayana_griffith_book6',15,'火神的证言','Agni''s witness','就在这时，天上的众神都来到了楞伽：财神俱比罗、阎摩、因陀罗、伐楼那、湿婆，还有四面的梵天，他们对罗摩说：你是宇宙的创造者，智者中的智者，为什么眼看着悉多走进火中却不阻止？','Then the gods came — Kubera, Yama, Indra, Varuṇa, Śiva and four-faced Brahmā — asking how Rāma, creator of the universe, could let Sītā enter the fire: did he not know who he was?','claim.v0330.ram_yuddha.15','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book6.16','storyver.hindu.ramayana_griffith_book6',16,'飞车还乡','Home in the flying chariot','第二天，维毗沙那请罗摩在楞伽城中沐浴、休息，享用盛宴，罗摩说：婆罗多为了我，在城外过着苦行者的日子，我怎么能先享受？','Vibhīṣaṇa offered baths and feasts, but Rāma would not rest while Bharata lived as an ascetic for his sake; the fourteen years were nearly up, and Bharata would enter the fire.','claim.v0330.ram_yuddha.16','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.hindu_ramayana_griffith_book6.17','storyver.hindu.ramayana_griffith_book6',17,'加冕','The coronation','婆罗多带着设睹卢祇那、三位母亲、大臣们和全城的百姓，捧着罗摩的那双鞋子，出城迎接。','Bharata came out with Śatrughna, the three queens, the ministers and the whole city, carrying the sandals.','claim.v0330.ram_yuddha.17','event.hindu.sita_abduction_rescue','place.hindu.lanka','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_1_12.1','storyver.greek.odyssey_butler_1_12',1,'众神的议事','The council of the gods','诗人请缪斯讲述那位足智多谋的英雄：他攻破了特洛伊神圣的城堡，此后到处漂泊，见过许多民族的城邦，懂得了他们的心思，在海上受了许多苦，只为保全自己的性命，带着同伴们回家。','The poet asks the Muse to tell of the man of many devices who sacked Troy''s citadel, saw many cities and learned many minds, suffered much at sea to save his life and bring his comrades home — and could not save them, for they perished by their own folly in eating the cattle of the Sun.','claim.v0330.ody_wanderings.01','event.greek.return_of_odysseus',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_1_12.2','storyver.greek.odyssey_butler_1_12',2,'忒勒马科斯与求婚人','Telemachus and the suitors','雅典娜穿上金色的鞋子，拿起长矛，从奥林匹斯山飞下，变作一个名叫门忒斯的外乡人，来到伊塔卡奥德修斯的宫门前。','Athena flew to Ithaca in the guise of Mentes, an old friend of Odysseus.','claim.v0330.ody_wanderings.02','event.greek.return_of_odysseus',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_1_12.3','storyver.greek.odyssey_butler_1_12',3,'没有织完的寿衣','The shroud that was never finished','第二天，忒勒马科斯召集伊塔卡人开会，这是奥德修斯离开以后的第一次。','Next day Telemachus called the first assembly since his father left and denounced the suitors devouring his house.','claim.v0330.ody_wanderings.03','event.greek.return_of_odysseus',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_1_12.4','storyver.greek.odyssey_butler_1_12',4,'皮洛斯与斯巴达','Pylos and Sparta','忒勒马科斯来到沙滩上的皮洛斯，老国王涅斯托耳正在海边向波塞冬献祭，热情地款待了他。','At sandy Pylos old Nestor welcomed him and told of the Greeks'' homecomings — Agamemnon murdered by his wife and Aegisthus and avenged by Orestes — but knew nothing of Odysseus, and sent his son to drive Telemachus to Sparta.','claim.v0330.ody_wanderings.04','event.greek.return_of_odysseus',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_1_12.5','storyver.greek.odyssey_butler_1_12',5,'卡吕普索放行','Calypso lets him go','众神又一次开会，雅典娜再次为奥德修斯求情，宙斯就派赫尔墨斯到卡吕普索的岛上去。','At a second council Zeus sent Hermes, who skimmed the sea like a gull to Ogygia, where Calypso''s cave was ringed with poplars and cypresses, hung with vines, watered by four springs through violet meadows — a sight to delight even a god — and fragrant with burning cedar as she sang at her golden loom.','claim.v0330.ody_wanderings.05','event.greek.return_of_odysseus',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_1_12.6','storyver.greek.odyssey_butler_1_12',6,'木筏与风暴','The raft and the storm','卡吕普索给了奥德修斯一把青铜斧和一把锛子，带他到岛的尽头，那里长着高大的桤木、白杨和松树。','With Calypso''s bronze axe Odysseus felled twenty trees and built a broad raft with mast, rudder and sail in four days.','claim.v0330.ody_wanderings.06','event.greek.return_of_odysseus',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_1_12.7','storyver.greek.odyssey_butler_1_12',7,'瑙西卡','Nausicaa','雅典娜来到费埃克斯国王阿尔喀诺俄斯的宫殿，走进公主瑙西卡的卧室，变作她的一个女伴，在梦中对她说：瑙西卡，你怎么这样懒散？','Athena appeared in a dream to the Phaeacian princess Nausicaa, as one of her friends, and told her to wash her fine clothes at the river, since she would soon marry.','claim.v0330.ody_wanderings.07','event.greek.return_of_odysseus',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_1_12.8','storyver.greek.odyssey_butler_1_12',8,'费埃克斯宫中的眼泪','Tears in the Phaeacian palace','雅典娜用一团浓雾把奥德修斯罩住，让他不被人看见，走进了阿尔喀诺俄斯的王宫。','Wrapped by Athena in mist, Odysseus entered the palace of King Alcinous — bronze walls, golden doors, silver posts, guarded by undying gold and silver dogs that Hephaestus made, beside an orchard fruiting all year round — and, as the mist cleared, clasped Queen Arete''s knees and begged passage home, which the king promised.','claim.v0330.ody_wanderings.08','event.greek.return_of_odysseus',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_1_12.9','storyver.greek.odyssey_butler_1_12',9,'基科涅斯人与食莲者','The Cicones and the Lotus-eaters','奥德修斯讲道：国王啊，我是伊塔卡人。','Odysseus told his tale.','claim.v0330.ody_wanderings.09','event.greek.return_of_odysseus',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_1_12.10','storyver.greek.odyssey_butler_1_12',10,'独眼巨人的山洞','The Cyclops''s cave','我们来到独眼巨人库克洛普斯的土地。','In the land of the Cyclopes — lawless giants who neither plough nor hold assemblies, each ruling his family in a mountain cave — Odysseus entered a huge cave with twelve men and a skin of strong wine given him by Maron, priest of Apollo.','claim.v0330.ody_wanderings.10','event.greek.return_of_odysseus',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_1_12.11','storyver.greek.odyssey_butler_1_12',11,'“没有人”','''Nobody''','我在洞里想出了一个计策。','Odysseus cut a length from the giant''s olive-wood club, long as a ship''s mast, had it sharpened and hardened in the fire and hid it in the dung; four men were chosen by lot to help him.','claim.v0330.ody_wanderings.11','event.greek.return_of_odysseus',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_1_12.12','storyver.greek.odyssey_butler_1_12',12,'羊腹下的逃亡与巨人的诅咒','Escape under the rams and the Cyclops''s curse','巨人呻吟着，摸索着推开洞口的巨石，自己坐在洞口，张开双手，想在我们出去时抓住我们。','Groaning, the blind giant rolled back the stone and sat in the entrance, hands spread to catch them.','claim.v0330.ody_wanderings.12','event.greek.return_of_odysseus',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_1_12.13','storyver.greek.odyssey_butler_1_12',13,'风袋与食人巨人','The bag of winds and the Laestrygonians','我们来到风神埃俄罗斯的浮岛，岛的四周围着青铜的城墙。','On the floating island of Aeolus, walled in bronze, the wind king hosted them a month and gave Odysseus an oxhide bag tied with silver cord, holding every wind but a gentle westerly to carry them home.','claim.v0330.ody_wanderings.13','event.greek.return_of_odysseus',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_1_12.14','storyver.greek.odyssey_butler_1_12',14,'喀耳刻的岛','Circe''s island','我们来到埃埃亚岛，那里住着美发的女神喀耳刻，她是太阳神赫利俄斯的女儿。','On Aeaea lived fair-haired Circe, daughter of Helios.','claim.v0330.ody_wanderings.14','event.greek.return_of_odysseus',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_1_12.15','storyver.greek.odyssey_butler_1_12',15,'冥府中的亡魂','Among the dead','我们乘着北风航行到世界的尽头，到了大洋河边终年雾气笼罩的辛梅里亚人的土地。','Sailing on the north wind to the edge of the world, to the misty land of the Cimmerians by the stream of Ocean, Odysseus dug a pit, poured milk and honey, wine and water, sprinkled barley and let the blood of a ram and a black ewe flow in.','claim.v0330.ody_wanderings.15','event.greek.return_of_odysseus',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_1_12.16','storyver.greek.odyssey_butler_1_12',16,'塞壬的歌声','The Sirens'' song','我们回到喀耳刻的岛上，埋葬了厄尔佩诺耳。','Back on Aeaea they buried Elpenor, and Circe warned of the dangers ahead: the Sirens sat in a flowery meadow heaped with rotting bones and shrivelled skin, and whoever heard their song forgot wife and children and never reached home.','claim.v0330.ody_wanderings.16','event.greek.return_of_odysseus',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_1_12.17','storyver.greek.odyssey_butler_1_12',17,'斯库拉与卡律布狄斯','Scylla and Charybdis','喀耳刻还告诉我：过了塞壬，你们会来到一道海峡，一边是高耸入云的悬崖，崖壁光滑，半腰上有一个山洞，洞里住着可怕的斯库拉，她的叫声像小狗一样，却是一个不死的怪物，长着十二只脚、六条长长的脖子，每条脖子上都有一个可怕的头，每张嘴里都有三排密密的牙齿。','Circe had also described the strait: on one side a sheer cliff with a cave halfway up where Scylla dwelt — yelping like a puppy, an immortal monster with twelve feet and six long necks, each with a hideous head and three rows of teeth, who would snatch six men from any passing ship; on the other a lower rock with a fig tree, beneath which divine Charybdis sucked down the black sea three times a day and spewed it out three times — and not even Poseidon could save a ship caught there.','claim.v0330.ody_wanderings.17','event.greek.return_of_odysseus',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_1_12.18','storyver.greek.odyssey_butler_1_12',18,'太阳神的牛','The cattle of the Sun','我们来到特里那喀亚岛，岛上放牧着太阳神赫利俄斯的七群牛和七群羊，每群五十头，它们不生也不死。','On Thrinacia grazed the Sun''s seven herds of cattle and seven flocks of sheep, fifty to each, never born and never dying.','claim.v0330.ody_wanderings.18','event.greek.return_of_odysseus',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_13_24.1','storyver.greek.odyssey_butler_13_24',1,'回到伊塔卡','Home to Ithaca','奥德修斯讲完了他的漂泊，费埃克斯人都沉默不语，被他的故事迷住了。','When Odysseus finished his tale the Phaeacians sat spellbound.','claim.v0330.ody_homecoming.01','event.greek.return_of_odysseus','place.greek.ithaca_homeric','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_13_24.2','storyver.greek.odyssey_butler_13_24',2,'牧猪人的茅屋','The swineherd''s hut','奥德修斯沿着崎岖的山路走到岛上的高处，来到牧猪人欧迈俄斯的院子。','Odysseus climbed to the swineherd Eumaeus''s stone-walled yard with its oak stockade and twelve sties.','claim.v0330.ody_homecoming.02','event.greek.return_of_odysseus','place.greek.ithaca_homeric','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_13_24.3','storyver.greek.odyssey_butler_13_24',3,'躲过埋伏','Escaping the ambush','这时在斯巴达，雅典娜来到忒勒马科斯的床前，对他说：你不该再离家这么远了，求婚人正在吞食你的家产，你的母亲也受到逼迫，要改嫁给欧律马科斯。','In Sparta Athena came to Telemachus''s bedside: he must go home, for the suitors were devouring his house and his mother was pressed to marry Eurymachus; and the worst of them lay in ambush in the strait between Ithaca and Samos, so he must keep clear of the islands, sail by night, send the ship on to the city and spend the night with the swineherd.','claim.v0330.ody_homecoming.03','event.greek.return_of_odysseus','place.greek.ithaca_homeric','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_13_24.4','storyver.greek.odyssey_butler_13_24',4,'父子相认','Father and son','天刚亮，奥德修斯和牧猪人正在茅屋里生火做早饭，听见院子里有脚步声，狗却没有叫，反而围着来人摇尾巴。','At dawn, as Odysseus and the swineherd made breakfast, steps sounded in the yard and the dogs fawned instead of barking: it was his son.','claim.v0330.ody_homecoming.04','event.greek.return_of_odysseus','place.greek.ithaca_homeric','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_13_24.5','storyver.greek.odyssey_butler_13_24',5,'老狗阿尔戈斯','Argos the old dog','忒勒马科斯回到宫中，老奶妈和母亲看见他，又惊又喜。','Telemachus returned to the palace and told his mother Menelaus''s news that Odysseus lived on Calypso''s island, while the seer Theoclymenus declared that Odysseus was already in Ithaca, plotting ruin for the suitors.','claim.v0330.ody_homecoming.05','event.greek.return_of_odysseus','place.greek.ithaca_homeric','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_13_24.6','storyver.greek.odyssey_butler_13_24',6,'大厅里的乞丐','The beggar in the hall','雅典娜催促奥德修斯到求婚人中间去讨饭，好看清楚谁善良、谁邪恶——尽管她并不打算放过任何一个。','Athena urged Odysseus to beg among the suitors to learn who was decent and who lawless — though she meant to spare none.','claim.v0330.ody_homecoming.06','event.greek.return_of_odysseus','place.greek.ithaca_homeric','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_13_24.7','storyver.greek.odyssey_butler_13_24',7,'老奶妈与伤疤','The nurse and the scar','夜里求婚人散去，奥德修斯和忒勒马科斯把大厅墙上的头盔、盾牌和长矛都搬进了储藏室，雅典娜举着一盏金灯为他们照明。','That night Odysseus and Telemachus carried the helmets, shields and spears from the hall into the storeroom while Athena lit their way with a golden lamp.','claim.v0330.ody_homecoming.07','event.greek.return_of_odysseus','place.greek.ithaca_homeric','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_13_24.8','storyver.greek.odyssey_butler_13_24',8,'鹅的梦与凶兆','The dream of the geese and the omens','珀涅罗珀又对乞丐说：请你为我解一个梦。','Penelope asked the beggar to read her dream: twenty geese she loved were eating grain when an eagle swooped from the mountain and broke all their necks; she wept, and the eagle returned, perched on the roof and said in a human voice that this was no dream but truth — the geese were the suitors, and he, once an eagle, was now her husband come home.','claim.v0330.ody_homecoming.08','event.greek.return_of_odysseus','place.greek.ithaca_homeric','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_13_24.9','storyver.greek.odyssey_butler_13_24',9,'奥德修斯的弓','The bow of Odysseus','珀涅罗珀用一把象牙柄的铜钥匙打开了深处的储藏室，从木钉上取下那张弓。','With a bronze key handled in ivory Penelope opened the inner storeroom and took down the bow, a gift from Iphitus whom Odysseus had met as a young man in Messene and which he had left at home as a keepsake.','claim.v0330.ody_homecoming.09','event.greek.return_of_odysseus','place.greek.ithaca_homeric','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_13_24.10','storyver.greek.odyssey_butler_13_24',10,'门槛上的复仇','Vengeance from the threshold','奥德修斯脱下破衣服，拿着弓和箭袋跳上大厅的门槛，把箭倒在脚前，说：这场比赛结束了，现在我要射另一个从来没人射过的目标，愿阿波罗让我成功。','Stripping off his rags, Odysseus leapt onto the threshold with bow and quiver and poured the arrows at his feet: the contest was over; now for another mark no man had hit.','claim.v0330.ody_homecoming.10','event.greek.return_of_odysseus','place.greek.ithaca_homeric','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_13_24.11','storyver.greek.odyssey_butler_13_24',11,'清洗宫殿','Cleansing the house','战斗结束了，求婚人一个也没有逃掉，像渔夫从海里拖上沙滩的鱼一样，横七竖八地躺在血泊和尘土里。','When the fighting was over not one suitor had escaped; they lay heaped in blood and dust like fish a fisherman has dragged onto the sand.','claim.v0330.ody_homecoming.11','event.greek.return_of_odysseus','place.greek.ithaca_homeric','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','原诗对不忠侍女与墨兰提俄斯的处死有具体描写；本篇只交代结果。','2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_13_24.12','storyver.greek.odyssey_butler_13_24',12,'床的秘密','The secret of the bed','老奶妈欢喜得两腿发软，跑上楼去，叫醒熟睡的珀涅罗珀：快醒醒，奥德修斯回来了，那个乞丐就是他，他把求婚人都杀了！','Weak-kneed with joy, Eurycleia woke Penelope: the beggar was Odysseus and had killed the suitors.','claim.v0330.ody_homecoming.12','event.greek.return_of_odysseus','place.greek.ithaca_homeric','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_13_24.13','storyver.greek.odyssey_butler_13_24',13,'果园里的父亲','The father in the orchard','赫尔墨斯手执金杖，把求婚人的鬼魂召出宫殿，它们像蝙蝠一样吱吱叫着跟在他后面，经过大洋河、白岩和太阳的门，来到长着日光兰的草地。','Hermes with his golden wand called the suitors'' souls from the palace, and they followed him squeaking like bats past the stream of Ocean, the White Rock and the gates of the Sun to the meadow of asphodel, where the shades of Achilles and Agamemnon were talking.','claim.v0330.ody_homecoming.13','event.greek.return_of_odysseus','place.greek.ithaca_homeric','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-24T01:00:00Z'),
('storyevent.v0330.greek_odyssey_butler_13_24.14','storyver.greek.odyssey_butler_13_24',14,'雅典娜的和平','Athena''s peace','求婚人被杀的消息很快传遍了全城，死者的亲属们哭喊着从宫中抬走尸体，各自安葬，又把别的岛上来的求婚人的尸体装上船，送回家乡。','News of the slaughter spread; the families carried off and buried their dead and shipped the island suitors home.','claim.v0330.ody_homecoming.14','event.greek.return_of_odysseus','place.greek.ithaca_homeric','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','第二十四卷的真伪自亚历山大里亚学者起就有争议，有人认为原诗止于第二十三卷夫妻团圆处。','2026-10-24T01:00:00Z');



UPDATE entities SET description='《西游记》中石头里生出的美猴王：大闹天宫，后来成为唐三藏的大徒弟。 / The stone-born Monkey King of Journey to the West, who wreaks havoc in heaven and becomes Tang Sanzang''s first disciple.',updated_at='2026-10-24T01:00:00Z' WHERE id='hero.chinese.sun_wukong' AND (description IS NULL OR description='');

INSERT OR IGNORE INTO story_series(
    id,title_zh,title_en,work_entity_id,primary_source_id,primary_civilization_id,description_zh,description_en,selection_note,featured_order,created_at,updated_at
) VALUES
('series.chinese.xiyouji','西游记连载','Journey to the West (series)','text.chinese.xiyouji','source.china.xiyouji.wikisource','civ.chinese_folk','按《西游记》百回本的回目顺序连读六部：美猴王出世与大闹天宫、取经缘起、师徒聚首、三打白骨精、真假美猴王、三调芭蕉扇，共九十一章。','Six parts read in the order of the hundred-chapter novel: the Monkey King''s birth and havoc in heaven, how the pilgrimage began, the pilgrims come together, the White Bone Demon, the two Monkey Kings and the plantain fan — ninety-one chapters in all.','本系列选讲第一至二十二回、第二十七至三十一回、第五十六至六十一回；其余回目（如五庄观、平顶山、红孩儿、通天河、女儿国及第六十二回以后的取经后半程）暂未收录，每部开头注明与上一部之间跳过的回目。',1,'2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('series.hindu.ramayana_books','罗摩衍那六篇连载','The Rāmāyaṇa in six books (series)','text.indian.ramayana','source.indian.ramayana_griffith.gutenberg','civ.hindu','按格里菲斯英译蚁垤本《罗摩衍那》的分卷连读六篇：童年篇、阿逾陀篇、森林篇、猴国篇、美妙篇、战斗篇，共八十七章。本站另有一篇二十章的全书概要版。','The six books of Vālmīki''s Rāmāyaṇa in Griffith''s translation read in order — Childhood, Ayodhyā, Forest, Kiṣkindhā, the Beautiful Book and War — eighty-seven chapters in all; a twenty-chapter overview of the whole epic is also available.','第七篇《后篇》（Uttara Kāṇḍa）一般认为是较晚增补的部分，本系列暂未收录；系列只讲蚁垤本这一个版本，不代表其他语言和地区的罗摩故事传统。',2,'2026-10-24T01:00:00Z','2026-10-24T01:00:00Z'),
('series.greek.odyssey','奥德赛连载','The Odyssey (series)','text.greek.odyssey','source.greek.odyssey_butler.gutenberg','civ.greek','按巴特勒英文散文译本《奥德赛》的二十四卷连读上下两部：上部漂泊（第一至十二卷），下部归家（第十三至二十四卷），共三十二章。','Butler''s prose Odyssey read in two parts across all twenty-four books: the wanderings (Books I–XII) and the homecoming (Books XIII–XXIV) — thirty-two chapters in all.','两部覆盖全部二十四卷，没有跳过的卷；分卷出自后世编订，只用于定位。',3,'2026-10-24T01:00:00Z','2026-10-24T01:00:00Z');

